insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('geegn-den-oidn-kochemea-bist-du-a-lealing-im-toschnschbueuelaklub', 'Geegn den oidn Kochemea bist du a Lealing im Toschnschbüülaklub!', '', '', '', 'Wiener Gaunersprache', 'Gegen den alten Kochemer bist du ein Lehrling im Taschenspielerclub!', '[{"kategorie": "wörtlich", "text": "\"Gegen den alten Vebrecherprofi bist du ein du ein Amateur mit Lego-Werkzeug!\"  2. Neben dem ausgekochten Berufsverbrecher bist du höchstens ein kleiner Praktikant im Ganovenchor!  3. Der war Meisterdieb, als du noch aufs Klettergerüst gepinkelt hast!"}]'::jsonb, ''),
  ('dea-hod-a-plottn-aum-plutza', 'Dea hod a Plottn aum Plutza!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat eine Platte am Schädel!', '[{"kategorie": "wörtlich", "text": "\"Der hat eine Vollglatze am Kopf!\"  2. Der ist komplett kahlköpfig!  3. Der ist obenrum total blank!  4. Der ist oben glatt wie ein Ei!"}]'::jsonb, ''),
  ('de-waatschn-is-gsessn-de-hod-richtig-pleschd', 'De Waatschn is gsessn - de hod richtig pleschd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Watsche ist gesessen - die hat richtig geplescht!', '[{"kategorie": "wörtlich", "text": "\"Die Ohrfeige hat voll eingeschlagen – das hat richtig gekracht!\"  2. Der Hieb war echt sauber – da hat''s ordentlich gescheppert!  3. Der Schlag war heftig – man hat''s richtig knallen gehört!"}]'::jsonb, ''),
  ('waunnsd-des-no-amoi-mochsd-pleschds', 'Waunnsd des no amoi mochsd, pleschds!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du das noch einmal machst, plescht''s!', '[{"kategorie": "wörtlich", "text": "\"Wenn du das noch einmal machst, kracht''s!\"  2. Mach das noch einmal – und du fängst dir eine!  3. Einmal noch – und es setzt was!"}]'::jsonb, ''),
  ('warad-ma-ned-olle-pleschd-wuan-haed-i-heit-no-meine-zeend', 'Warad ma ned olle pleschd wuan, häd I heit no meine Zeend!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wären wir nicht alle geplescht worden, hätte ich heute noch meine Zähne!', '[{"kategorie": "wörtlich", "text": "\"Wenn sie uns nicht so verdroschen hätten, wär mein Gebiss noch original!\"  2. Hätten wir nicht alle so eine Abreibung kassiert, hätt ich noch alle Kauleisten beisammen!  3. Wären wir damals nicht alle wie Sandsäcke bearbeitet worden, hätt ich jetzt weniger Titan im Kiefer!"}]'::jsonb, ''),
  ('i-plesch-da-glei-aane', 'I plesch da glei aane!', '', '', '', 'Wiener Gaunersprache', 'Ich plesche dir gleich eine!', '[{"kategorie": "wörtlich", "text": "\"Ich hau dir gleich eine runter!\"  2. Gleich gibt''s eine geklatscht!  3. Ich [[ditsch]] dir gleich eine!  4. Ich polier dir gleich die Fresse!"}]'::jsonb, ''),
  ('dea-pleschd-de-schdrossn-owe-wiara-gsengde-sau', 'Dea pleschd de Schdrossn owe wiara gsengde Sau!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der plescht die Straße runter wie eine gesengte Sau!', '[{"kategorie": "wörtlich", "text": "\"Der rast dahin wie eine Sau, der man beim Schlachten gerade die Haut abbrennt!\"  2. \"Der schießt die Straße runter wie ein Wahnsinniger!\"  3. \"Der brettert die Straße runter wie ein Irrer!\""}]'::jsonb, ''),
  ('do-pleschds-owe-wiar-aus-kiiwaen', 'Do pleschds owe wiar aus Kiiwän!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da plescht es runter wie aus Kübeln!', '[{"kategorie": "wörtlich", "text": "\"Da regnet es runter wie aus [[Kübeln]]!\"  2. Da schüttet es wie aus Eimern!\"  3. Da gießt es in Strömen!"}]'::jsonb, ''),
  ('do-pledads-owe-wiar-aus-kiiwaen', 'Do pledads owe wiar aus Kiiwän!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da pledert es runter wie aus Kübeln!', '[{"kategorie": "wörtlich", "text": "\"Da regnet es runter wie aus [[Kübeln]]!\"  2. Da schüttet es wie aus Eimern!\"  3. Da gießt es in Strömen!"}]'::jsonb, ''),
  ('do-daschlds-owe', 'Do daschlds owe!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da taschelt es runter!', '[{"kategorie": "wörtlich", "text": "\"Da regnet es runter wie aus [[Kübeln]]!\"  2. Da schüttet es wie aus Eimern!\"  3. Da gießt es in Strömen!"}]'::jsonb, ''),
  ('noochn-drittn-plescha-woar-endlich-a-rua', 'Noochn drittn Plescha woar endlich a Rua!', '', '', '', 'Wiener Gaunersprache', 'Nach dem dritten Plescher war endlich Ruhe!', '[{"kategorie": "wörtlich", "text": "\"Nach dem dritten Plescher war endlich Ruhe im Karton!\"  2. Drei saubere Ohrfeigen – und der Zirkus war vorbei!  3. Nach drei Watschen war endlich Funkstille!"}]'::jsonb, ''),
  ('do-is-auf-amoi-a-plescha-daheakumma-dass-ma-bis-aufd-untagattn-noss-woan', 'Do is auf amoi a Plescha daheakumma, dass ma bis aufd Untagattn noss woan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da ist plötzlich a Plescher dahergekommen, dass wir bis auf die Untergatten nass waren!', '[{"kategorie": "wörtlich", "text": "\"Plötzlich kam ein Regenguss runter, und wir waren in Sekunden bis auf die Unterhosen klatschnass!\"  2. Plötzlich ging ein Wolkenbruch nieder, und wir waren in Sekunden pitschnass bis auf die Knochen!  3. Aus dem Nichts öffnete der Himmel seine Schleusen, und ehe wir uns versahen, standen wir bis auf die Haut unter Wasser!"}]'::jsonb, ''),
  ('auf-amoi-hods-an-plescha-gmochd-und-ea-is-aum-boodn-gleeng', 'Auf amoi hods an Plescha gmochd, und ea is aum Boodn gleeng!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auf einmal hat es einen Plescher gemacht, und er ist am Boden gelegen!', '[{"kategorie": "wörtlich", "text": "\"Plötzlich gab es einen lauten Knall, und er lag am Boden!\"  2. Auf einmal hat’s gekracht – und er lag wie ein nasser Sack am Boden!  3. Plötzlich hat''s gescheppert – und schon hat er den Boden geküsst!"}]'::jsonb, ''),
  ('da-plescha-woar-friara-in-jeedn-haus-a-standardweakzeig-zum-klopfn-schdaumpfn-und-dengln', 'Da Plescha woar friara in jeedn Haus a Standardweakzeig - zum Klopfn, Schdaumpfn und Dengln!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Plescher war früher in jedem Haus ein Standardwerkzeug – zum Klopfen, Stampfen, Dengeln!', '[{"kategorie": "wörtlich", "text": "\"Früher fand man den Plescher in jedem Haushalt – ein echtes Allzweckwerkzeug zum Klopfen, Stampfen und [[Dengeln]]!\"  2. Der Plescher gehörte früher zur Grundausstattung – ob zum Wäscheklopfen, Stampfen oder Schärfen!  3. Der Plescher war einst der Hammer der Hausfrau – universell einsetzbar von der Wäsche bis zum Sensenblatt!"}]'::jsonb, ''),
  ('do-soi-doch-glei-a-dunnaweeda-dreipleschn', 'Do soi doch glei a Dunnaweeda dreipleschn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da soll doch gleich ein Donnerwetter dreinpleschen!', '[{"kategorie": "wörtlich", "text": "\"Da soll gleich der Blitz einschlagen, wenn das noch länger so weitergeht!\"  2. Jetzt reicht’s aber! Da braucht’s ein Donnerwetter mit Nachhall!  3. Gleich hagelt’s hier Donnerworte!"}]'::jsonb, ''),
  ('i-kennt-mit-da-faust-dreipleschn', 'I kennt mit da Faust dreipleschn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich könnte mit der Faust dreinpleschen!', '[{"kategorie": "wörtlich", "text": "\"Ich bin kurz davor, meine Faust sprechen zu lassen!\"  2. Ich platze gleich vor Wut!  3. Das macht mich fuchsteufelswild!"}]'::jsonb, ''),
  ('i-hob-eam-in-oasch-oopleschd-dassa-via-wochn-ned-sitzn-kau', 'I hob eam in Oasch oopleschd, dassa via Wochn ned sitzn kau!', '', '', '', 'Wiener Gaunersprache', 'Ich hab ihm den Arsch abgeplescht, dass er vier Wochen nicht sitzen kann!', '[{"kategorie": "wörtlich", "text": "\"Ich hab ihm den Arsch versohlt, dass er jetzt vier Wochen nicht sitzen kann!\"  2. Ich hab ihm das Sitzfleisch weichgeklopft, dass er jetzt vier Wochen nur noch stehen kann!  3. Ich hab ihm das Gesäß windelweich geprügelt, dass er jetzt nur noch im Stehen scheißen kann!"}]'::jsonb, ''),
  ('wea-mit-da-sensn-oaweitn-wueue-brauchd-ned-nua-kroft-sondan-aa-an-guadn-denglhaumma', 'Wea mit da Sensn oaweitn wüü, brauchd ned nua Kroft, sondan aa an guadn Denglhaumma!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wer mit der Sense arbeiten will, braucht nicht nur Kraft, sondern auch einen guten Dengelhammer!', '[{"kategorie": "wörtlich", "text": "\"Wenn du mit der Sense arbeiten willst, brauchst du nicht nur Kraft, sondern auch eine scharfe Schneid – und die macht der Dengelhammer!\"  2. Zum Dengeln einer Sense gehört mehr als Muskelkraft – es braucht das passende Werkzeug!  3. Eine scharfe Sense gibt''s nicht durch Kraft allein, sondern nur mit einem guten Dengelhammer!"}]'::jsonb, ''),
  ('dera-ia-fotzblaeaezn-schaud-echt-so-aus-ois-haedads-min-loeoetkoibm-knuutschd', 'Dera ia Fotzblääzn schaud echt so aus, ois hädads min Löötkoibm knuutschd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der ihre Fotzbletz''n schaut echt so aus, als hätte sie mit''m Lötkolben geknutscht!', '[{"kategorie": "wörtlich", "text": "\"Ihr Fieberbläschen schaut aus, als hätte ihr einer ’nen Lötkolben auf die Lippe gedrückt\"  2. Bei der Fieberblase auf ihrer Lippe könnte man fast glauben, sie hat versucht, ''nen Heizstab zu lutschen!  3. Mit dem Fieberherpes schaut sie aus, als hätt sie vom Teufel ''nen Zungenkuss bekommen!"}]'::jsonb, ''),
  ('des-reindl-hod-a-blaeaezn', 'Des Reindl hod a Blääzn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Reindl hat eine Bletzen!', '[{"kategorie": "wörtlich", "text": "\"Der Topf hat eine abgeplatzte Stelle!\"  2. An dem Topf ist ein Stück der Beschichtung abgesplittert!  3. Der Lack am Topf ist abgeblättert!"}]'::jsonb, ''),
  ('i-hob-do-a-blaeaezn-aum-oeoeboogn-de-seit-wochn-ned-zuahaeud', 'I hob do a Blääzn aum Ööboogn, de seit Wochn ned zuahäud!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ich habe da eine Beltzen am Ellbogen, die seit Wochen nicht zuheilt!', '[{"kategorie": "wörtlich", "text": "\"Ich habe da eine entzündete Hautstelle am Ellbogen, die seit Wochen nicht abheilt!\"  2. Ich hab da ''ne Schrunde am Ellbogen, die nicht zugeht und mich seit Wochen nervt!  3. Ich hab da ''ne aufgesprungene Hautstelle am Ellbogen - die will einfach nicht heilen!"}]'::jsonb, ''),
  ('dea-boofaed-wiara-schloot', 'Dea boofäd wiara Schloot!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der pofelt wie ein Schlot!', '[{"kategorie": "wörtlich", "text": "\"Der raucht wie ein Schlot!\"  2. Der qualmt eine nach der anderen!  3. Der raucht sich das Gehirn weich!"}]'::jsonb, ''),
  ('i-hob-kaa-aunung-wos-dea-do-wiida-boofaed-hod-fia-mi-woa-des-a-aanzigs-tohuwabohu', 'I hob kaa Aunung, wos dea do wiida boofäd hod - fia mi woa des a aanzigs Tohuwabohu!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hab keine Ahnung, was er da wieder gepofelt hat – für mich war das ein einziges Tohuwabohu!', '[{"kategorie": "wörtlich", "text": "\"Ich hab keine Ahnung, was er da wieder gepofelt hat – für mich war das ein einziges Durcheinander!\"  2. Ich hab keine Ahnung, was der da wieder von sich gegeben hat - für mich war das ein einziger Wortsalat!  3. Ich habe den Faden komplett verloren bei dem, was er da erzählt hat - seine Worte ergaben für mich keinerlei Sinn!"}]'::jsonb, ''),
  ('waunn-dea-boofla-niast-kumman-iwaroi-klaane-rauchwoikn-aus-eam-aussa', 'Waunn dea Boofla niast, kumman iwaroi klaane Rauchwoikn aus eam aussa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn dieser Pofler niest, kommen überall kleine Rauchwolken aus ihm raus!', '[{"kategorie": "wörtlich", "text": "\"Wenn dieser Kettenraucher niest, kommen überall kleine Rauchwolken aus ihm raus!\"  2. Wenn dieser Kettenraucher niest, entsteigen seiner Nase kleine Rauchwölkchen! Wenn dieser Kettenraucher niest, qualmt’s aus seiner Nase wie aus ’nem Auspuff!"}]'::jsonb, ''),
  ('ollas-boofaed-bei-da-kiachn-ausse', 'Ollas boofäd bei da Kiachn ausse!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alles pofelt bei der Kirche hinaus!', '[{"kategorie": "wörtlich", "text": "\"Alle drängen sich bei der Kirche hinaus!\"  2. Alles ergießt sich aus der Kirche ins Freie!  3. Alle strömen aus der Kirche hinaus ins Freie!"}]'::jsonb, ''),
  ('de-leid-boofaen-duach-de-gossn', 'De Leid boofän duach de Gossn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Die Leute pofeln durch die Gassen!', '[{"kategorie": "wörtlich", "text": "\"Die Leute drängen sich durch die Gassen!\""}, {"kategorie": "", "text": "\"Dicht an dicht schieben sich die Leute durch die Straßen!\"  3. \"Durch die Gassen ergießt sich ein unaufhörlicher Strom von Menschen!\""}]'::jsonb, ''),
  ('hund-miassn-draussdn-bleibm', 'Hund miassn draussdn bleibm!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hunde müssen draußen bleiben!', '[{"kategorie": "wörtlich", "text": "\"Hunde bitte draußen lassen!\"  2. Wir bitten um Verständnis: Hunde dürfen nicht mit hinein!  3. Bitte keine Hunde im Innenbereich!"}]'::jsonb, ''),
  ('da-dreck-untan-daeaewich-is-schoo-joazeente-oid', 'Da Dreck untan Dääwich is schoo Joazeente oid!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Dreck unter''m Teppich ist schon Jahrzehnte alt!', '[{"kategorie": "wörtlich", "text": "\"Der Schmutz unter dem Teppich ist schon Jahrzehnte alt!\"  2. Unter''m Teppich gammelt der Staub seit der Steinzeit!  3. Da unterm Teppich pickt der [[Grind]] von drei Jahrzehnten!"}]'::jsonb, ''),
  ('kaa-dreck-ned', 'Kaa Dreck ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Kein Dreck nicht!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Pappenstiel!\"  2. Das ist kein Klacks!  3. Das hat’s in sich!  4. Das ist nicht ohne!  5. [[Des is kaa Leachalschaas!]]  6. [[Des is kaa Bemmal ned!]]  7. [[Kaa Schaas ned!]]"}]'::jsonb, 'Kaa Schaas ned!'),
  ('kaa-schaas-ned', 'Kaa Schaas ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Kein Schas nicht!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Pappenstiel!\"  2. Das ist kein Klacks!  3. Das hat’s in sich!  4. Das ist nicht ohne!  5. [[Des is kaa Leachalschaas!]]  6. [[Des is kaa Bemmal ned!]]  7. [[Kaa Dreck ned!]]"}]'::jsonb, 'Kaa Dreck ned!'),
  ('wos-soi-i-mit-dem-dreck-aufaunga-hau-s-in-mist', 'Wos soi I mit dem Dreck aufaunga? Hau''s in Mist!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was soll ich mit dem Dreck anfangen - hau''s in den Mist!', '[{"kategorie": "wörtlich", "text": "\"Was soll ich mit dem Ramsch anfangen? Wirf''s weg!\"  2. Was soll ich mit dem Schrott? Ab in den Müll damit!  3. Damit kann ich nichts anfangen – der Plunder gehört auf den Müllhaufen!"}]'::jsonb, ''),
  ('du-schdinkads-dreckfaadl', 'Du schdinkads Dreckfaadl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du stinkendes Dreckfadel!', '[{"kategorie": "wörtlich", "text": "\"Du stinkendes Dreckschweinchen!\"  2. Du verlotterte Schmutznudel!  3. Du versiffter Drecksau!"}]'::jsonb, ''),
  ('dea-laatschd-dahea-wiara-dreckfaadl-ausn-koellaloch', 'Dea laatschd dahea wiara Dreckfaadl ausn Köllaloch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der latscht daher wie ein Dreckfadel aus’m Kellerloch!', '[{"kategorie": "wörtlich", "text": "\"Der schlurft daher wie ein Dreckschweinchen, das im Kellerloch haust!\"  2. Der Schmutzfink kommt daher wie frisch aus der Mülltonne!  3. Der latscht daher, als würde er seit Wochen obdachlos im Erdkeller hausen!"}]'::jsonb, ''),
  ('mit-seina-rostign-dreckschleida-vasauda-uns-de-gaunze-luft', 'Mit seina rostign Dreckschleida vasauda uns de gaunze Luft!', '', '', '', 'Wiener Mechaniker-Slang', 'Mit seiner rostigen Dreckschleuder versaut er uns die ganze Luft!', '[{"kategorie": "wörtlich", "text": "\"Mit seiner rostigen Abgasschleuder verpestet er uns die ganze Luft!\"  2. Der rattert mit seiner Stinkkarre durch unsere Gasse und versifft uns die ganze Luft!  3. Mit seiner stinkenden Rostmühle raucht er uns die ganze Gasse zu!"}]'::jsonb, ''),
  ('de-dreckschleida-lossd-ka-guads-hoa-aun-iagendwem', 'De Dreckschleida lossd ka guads Hoa aun iagendwem!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Dreckschleuder lässt kein gutes Haar an irgendwem!', '[{"kategorie": "wörtlich", "text": "\"Dieses Lästermaul lässt kein gutes Haar an irgendwem!\"  2. Diese Tratschtrommel lästert über alles und jeden!  3. Dieses Schandmaul sabbert Gift und Galle über jeden, der atmet!"}]'::jsonb, ''),
  ('dea-hod-ned-nua-huastn-und-schnupfn-dea-is-a-dreckschleida-mit-schleimkanoon', 'Dea hod ned nua Huastn und Schnupfn - dea is a Dreckschleida mit Schleimkanoon!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der hat nicht nur Husten und Schnupfen – der ist ''ne Dreckschleuder mit Schleimkanone!', '[{"kategorie": "wörtlich", "text": "\"Der hat nicht nur Husten und Schnupfen – der ist ''ne Bazillenschleuder mit Schleimkanone!\"  2. Der hustet und schnieft, als wär er ne wandelnde Seuchenzentrale!  3. Wenn diese Seuchenschleuder niest und hustet, brauchst du ''nen Ganzkörperanzug!"}]'::jsonb, ''),
  ('hoid-obschdaund-du-waundlnde-bazueuenschleida-oda-wueuest-deine-scheiss-viarn-auf-mia-vataeun', 'Hoid Obschdaund, du waundlnde Bazüünschleida - oda wüüst deine Scheiss-Viarn auf mia vatäun?', '', '', '', 'Krank & kuriert auf Wienerisch', 'Halt Abstand, du wandelnde Bazillenschleuder - oder willst du deine Scheiß-Viren auf mir verteilen?', '[{"kategorie": "wörtlich", "text": "\"Bleib mir vom Leib, du rotzende Seuchenschleuder - oder willst du deine Scheiß-Viren auf mir verteilen?\"  2. Geh weg, du hustende Biogranate – ich hab keinen Bock auf dein Virenkonfetti!  3. Hau ab, du rotzende Dreckschleuder – ich brauch heut keine Gratisgrippe!"}]'::jsonb, ''),
  ('schleich-di-du-rotzade-seichnschleida-deine-bazueuen-wueue-do-kaana', 'Schleich di, du rotzade Seichnschleida - deine Bazüün wüü do kaana!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Schleich dich, du rotzende Seuchenschleuder - deine Bazillen will da keiner!', '[{"kategorie": "wörtlich", "text": "\"Verpiss dich, du rotzender Virenherd - deine Bazillen will hier keiner!\"  2. Verschwinde, du rotzende Virenschleuder - deine Pest braucht hier keiner!  3. Hau sofort ab, du rotzende Keimschleuder - und nimm deine Bazillen gleich mit nach Hause!"}]'::jsonb, ''),
  ('si-schaud-jo-liab-aus-owa-ia-rotzade-oat-is-ned-zum-aushoidn', 'Si schaud jo liab aus - owa ia rotzade Oat is ned zum Aushoidn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie schaut ja lieb aus - aber ihre rotzerte Art ist nicht zum Aushalten!', '[{"kategorie": "wörtlich", "text": "\"Sie sieht ja lieb aus - aber ihre rotzfreche Art ist nicht zu ertragen!\"  2. Auf den ersten Blick wirkt sie nett – aber ihre respektlose Art ist schwer auszuhalten!  3. Sie schaut ja ganz süß aus – aber ihre große Klappe macht alles kaputt!"}]'::jsonb, ''),
  ('du-dreckade-schlaumpn-gee-zruck-in-dein-koella', 'Du dreckade Schlaumpn - gee zruck in dein Kölla!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du dreckige Schlampe - geh zurück in deinen Keller!', '[{"kategorie": "wörtlich", "text": "\"Du verdrecktes Luder - kriech zurück in deinen feuchten Keller!\"  2. Du verwahrloste Kellerhexe – verschwinde dahin, wo du hergekommen bist!  3. Du halbverweste Drecksziege – ab in den Keller mit dir, keiner will dich hier oben sehen!"}]'::jsonb, ''),
  ('schau-ned-so-traurig-drei-muang-is-aa-no-a-toog', 'Schau ned so traurig drei, muang is aa no a Toog!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schau nicht so traurig drein - morgen ist auch noch ein Tag!', '[{"kategorie": "wörtlich", "text": "\"Schau nicht so bedrückt - morgen ist auch noch ein Tag!\"  2. \"Mach nicht so ein langes Gesicht – morgen sieht die Welt schon wieder anders aus!\"  3. Stell das Trauergesicht ab – der nächste Tag kommt garantiert!"}]'::jsonb, ''),
  ('do-miassad-ma-moi-uandlich-dreihaun', 'Do miassad ma moi uandlich dreihaun!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da müsste man mal ordentlich dreinhauen!', '[{"kategorie": "wörtlich", "text": "\"Da müsste man mal ordentlich dazwischenfahren!\"  2. Da sollte man mal ordentlich dazwischenfunken!  3. Da müsste man mal ordentlich reindreschen, bevor’s völlig aus dem Ruder läuft!"}]'::jsonb, ''),
  ('do-miassad-ma-moi-uandlich-dreifoan', 'Do miassad ma moi uandlich dreifoan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da müsste man mal ordentlich dreinfahren!', '[{"kategorie": "wörtlich", "text": "\"Da müsste man mal ordentlich dazwischenfahren!\"  2. Da sollte man mal ordentlich dazwischenfunken!  3. Da müsste man mal ordentlich reindreschen, bevor’s völlig aus dem Ruder läuft!"}]'::jsonb, ''),
  ('ned-dreischnoowaen-waunn-d-frau-reedt', 'Ned dreischnoowän, waunn d''Frau reedt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nicht dreinschnabeln, wenn die Frau redet!', '[{"kategorie": "wörtlich", "text": "\"Quatsch nicht dazwischen, wenn die Frau spricht!\"  2. Schnatter nicht dazwischen, wenn die Frau das Wort hat!  3. Die Königin spricht – also Schnabel zu!"}]'::jsonb, ''),
  ('i-loss-ma-von-dera-sicha-nix-dreireedn', 'I loss ma von dera sicha nix dreireedn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich lass mir von der sicher nichts dreinreden!', '[{"kategorie": "wörtlich", "text": "\"Von der lass ich mir gar nichts sagen!\"  2. Ich lass mir von ihr sicher nicht vorschreiben, was ich zu tun habe!  3. Ich lasse mir da nicht reinreden - das entscheide ich ganz allein, und nicht sie!\""}]'::jsonb, ''),
  ('des-fotzhoowae-solo-woa-echt-leiwaund-bis-da-zeigla-dreipotzd-is', 'Des Fotzhoowä-Solo woa echt leiwaund, bis da Zeigla dreipotzd is!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Das Fotzhobel-Solo war echt leiwand, bis der Schlagzeuger dreingepatzt ist!', '[{"kategorie": "wörtlich", "text": "\"Das Mundharmonikasolo war richtig stark – bis der Schlagzeuger den Einsatz vermasselt hat!\"  2. Das Mundharmonikasolo war großartig – bis der Drummer danebengehauen hat!  3. Das Mundharmonikasolo war echt geil – bis der Schlagzeuger reingecrasht ist!"}]'::jsonb, 'Echt leiwaund!'),
  ('do-hod-wiida-wea-dreipfuschd-und-jetzt-is-ollas-hii', 'Do hod wiida wea dreipfuschd - und jetzt is ollas hii!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Da hat wieder wer dreingepfuscht - und jetzt ist alles hin!', '[{"kategorie": "wörtlich", "text": "\"Da hat wieder wer dazwischengepfuscht - – und jetzt ist alles kaputt!\"  2. Da hat jemand wieder reingepfuscht - und jetzt ist alles im Eimer!  3. Typisch: einer muss wieder reinmurksen – und zack, alles hinüber!"}]'::jsonb, ''),
  ('drin-bist-schnoeoe-owa-draus-kummsd-nimma', 'Drin bist schnöö, owa draus kummsd nimma!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Drinnen bist du schnell, aber raus kommst du nimmer!', '[{"kategorie": "wörtlich", "text": "\"Einmal drin, kommst du nicht mehr raus!\"  2. Rein geht''s schnell – aber raus wird’s schwierig!  3. Reinzukommen ist leicht, aber rauszukommen ist fast unmöglich!"}]'::jsonb, ''),
  ('waunn-des-drauskummd-samma-im-oasch', 'Waunn des drauskummd, samma im Oasch!', '', '', '', 'Wiener Gaunersprache', 'Wenn das drauskommt, sind wir im Arsch!', '[{"kategorie": "wörtlich", "text": "\"Wenn das herauskommt, sind wir geliefert!\"  2. Sollte das bekannt werden, sind wir echt am Arsch!  3. Wenn das ans Licht kommt, sind wir fällig!"}]'::jsonb, ''),
  ('und-wos-kummd-do-draus', 'Und wos kummd do draus?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Und was kommt da draus?', '[{"kategorie": "wörtlich", "text": "\"Und was kommt dabei raus?\"  2. \"Und was läuft am Ende dabei raus?\"  3. Und was ergibt sich daraus?  4. Was bringt das eigentlich?"}]'::jsonb, ''),
  ('momental-jetzt-bin-i-komplett-drauskumma-wo-woa-ma-nomoi', 'Momental, jetzt bin I komplett drauskumma - wo woa ma nomoi?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Momenterl, jetzt bin ich komplett drausgekommen – wo waren wir nochmal?', '[{"kategorie": "wörtlich", "text": "\"Momentchen, jetzt bin ich komplett rausgekommen – wo waren wir nochmal?\"  2. Augenblick, ich hab kurz den Faden verloren – wo waren wir nochmal?  3. Warte mal – ich bin komplett raus, wo waren wir nochmal?"}]'::jsonb, ''),
  ('momental-zeaschd-de-marii', 'Momental, zeaschd de Marii!', '', '', '', 'Wiener Gaunersprache', 'Momenterl, zuerst die Marie!', '[{"kategorie": "wörtlich", "text": "\"Moment mal, zuerst das Geld!\"  2. Momentchen – erst wird gezahlt!  3. Einen Augenblick – zuerst die Kohle, dann der Rest!"}]'::jsonb, ''),
  ('da-glaumpfnwiaga-is-beim-solo-drauskumma-und-hod-si-daunn-nimma-gfaungan', 'Da Glaumpfnwiaga is beim Solo drauskumma und hod si daunn nimma gfaungan!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Der Klampfenwürger ist beim Solo drausgekommen und hat sich dann nicht mehr gefangen!', '[{"kategorie": "wörtlich", "text": "\"Der Gitarrist ist beim Solo rausgekommen und hat sich dann nicht mehr gefangen!\"  2. Der Gitarrist hat sich im Solo verrannt und nicht mehr zurückgefunden!  3. Der Gitarrist hat sich bei seinem Solo verspielt und danach nicht mehr ins Stück gefunden!"}]'::jsonb, ''),
  ('kenntasd-bitte-in-mist-drausbringa', 'Kenntasd bitte in Mist drausbringa?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Könntest bitte den Mist drausbringen?', '[{"kategorie": "wörtlich", "text": "\"Kannst du bitte den Müll rausbringen?\"  2. Könntest du bitte den Mist rausstellen?  3. Kannst du bitte den Müll hinaustragen?"}]'::jsonb, ''),
  ('ea-hod-a-neichs-album-drausbrochd-huach-amoi-eine', 'Ea hod a neichs Album drausbrochd - huach amoi eine!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Er hat ein neues Album drausgebracht - horch mal rein!', '[{"kategorie": "wörtlich", "text": "\"Er hat ein neues Album herausgebracht - hör mal rein!\"  2. Er hat ein neues Album veröffentlicht – hör es dir mal an!  3. Sein neues Album ist draußen – und es knallt! Hör unbedingt rein!"}]'::jsonb, ''),
  ('den-kau-nix-drausbringa-ka-vahea-ka-zeig-ka-owahaeae', 'Den kau nix drausbringa - ka Vahea, ka Zeig, ka Owahää!', '', '', '', 'Wiener Gaunersprache', 'Den kann nichts drausbringen - kein Verhör, kein Zeuge, keine Oberhöh!', '[{"kategorie": "wörtlich", "text": "\"Den kann nichts durcheinanderbringen - kein Verhör, kein Zeuge, keine Polizeiobrigkeit!\"  2. Den bringt nichts aus der Fassung – weder Verhöre, noch Zeugen, noch Sonderermittler!  3. Den knackt keiner – kein [[Kieberer]], kein Staatsanwalt, kein [[Zund]]!"}]'::jsonb, ''),
  ('i-hob-gschdoodad-wiara-hiinnichs-tonbandl-und-aum-schluss-hob-i-goa-nix-mea-drausbrocht', 'I hob gschdoodad wiara hiinnichs Tonbandl - und aum Schluss hob I goa nix mea drausbrocht!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hab gestottert wie ein hinniges Tonbandl - und am Schluss hab ich gar nichts mehr drausgebracht!', '[{"kategorie": "wörtlich", "text": "\"Ich hab gestottert wie ein kaputtes Tonbandl - und am Schluss hab ich gar nichts mehr rausgebracht!\"  2. Meine Zunge war wie verknotet – am Schluss hab ich keinen Ton mehr rausgebracht!  3. Ich war so nervös, dass ich nur noch gestottert hab – und am Ende ging dann gar nichts mehr!"}]'::jsonb, ''),
  ('de-bochschdoeoezn-schdoiziad-umanaund-ois-warads-aum-laufschdeed-a-klaana-augeeba-hoid-mit-feedakroong', 'De Bochschdöözn schdoiziad umanaund, ois warads aum Laufschdeed - a klaana Augeeba hoid, mit Feedakroong!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Die Bachstelze stolziert herrum, als wäre sie auf dem Laufsteg – ein kleiner Angeber halt, mit Federkragen!', '[{"kategorie": "wörtlich", "text": "\"Die Bachstelze stakst da rum, als wär sie auf dem Laufsteg – kleiner Angeber mit Federkragen!\"  2. Da stolziert die Bachstelze wieder rum, als wär sie auf ''ner Modenschau!  3. Die Bachstelze stakt da rum wie ''ne kleine Federdiva - als hätt sie den ganzen Fluss als Catwalk für sich allein gemietet!"}]'::jsonb, ''),
  ('friara-in-da-schui-haums-zu-ia-imma-bochschdoeoezn-gsoogd-launge-fiass-wia-duenne-zaunschdoocha-owa-sunst-nix-drau', 'Friara in da Schui haums zu ia imma ''Bochschdöözn'' gsoogd - launge Fiass wia dünne Zaunschdoocha, owa sunst nix drau!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Früher in der Schule haben sie zu ihr immer ''Bachstelze'' gesagt - lange Füße wie Zahnstocher, aber sonst nichts dran!', '[{"kategorie": "wörtlich", "text": "\"Früher in der Schule haben sie zu ihr immer ''Bachstelze'' gesagt - lange Beine wie Zahnstocher, aber sonst nichts dran!\"  2. In der Schule nannten sie sie immer ''Bachstelze'' – ellenlange Stelzen, aber sonst nur Haut und Knochen!  3. Alle haben sie damals nur ''Bachstelze'' genannt – lange, dünne Beine, aber mehr Knochen als Kurven!"}]'::jsonb, ''),
  ('oida-schau-wia-schee-rood-sa-si-de-backaln-fia-uns-augmoind-hod', 'Oida, schau, wia schee rood sa si de Backaln fia uns augmoind hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Alter, schau, wie schön rot sie sich die Backerln für uns angemalt hat!', '[{"kategorie": "wörtlich", "text": "\"Ey, guck mal, wie knallrot sie sich die Wangen geschminkt hat – voll süß irgendwie!\"  2. Boah, sie hat sich ihre Pausbäckchen echt hübsch angemalt – schön dunkelrot, sieht voll nach Date-Night aus!  3. Junge, check mal ihre Kullerbäckchen – knallrot wie gemalt, die hat sich voll Mühe gegeben!"}]'::jsonb, ''),
  ('de-backaln-egal-ob-vom-schweindl-vom-rind-oda-vom-fisch-san-a-untaschaetzde-delikatess', 'De Backaln - egal ob vom Schweindl, vom Rind oda vom Fisch - san a untaschätzde Delikatess!', '', '', '', 'Wiener Fleischhauer-Slang', 'Die Backerln - egal ob vom Schwein, vom Rind oder vom Fisch - sind eine unterschätzte Delikatesse!', '[{"kategorie": "wörtlich", "text": "\"Die Bäckchen - egal vom Schwein, Rind oder Fisch - sind eine weithin unterschätzte Delikatesse!\"  2. Die Bäckchen vom Schwein, Rind oder Fisch gehören zu den feinsten, aber oft übersehenen Genussstücken!  3. Das zarte Wangenfleisch von Schwein, Rind oder Fisch ist eine Delikatesse, die noch viel zu wenig Beachtung findet!"}]'::jsonb, ''),
  ('schweinsbackaln-muassd-schdundnlaung-bei-niidriga-temparatua-dinstn-daunn-zageengans-da-auf-da-zungan', 'Schweinsbackaln muassd schdundnlaung bei niidriga Temparatua dinstn - daunn zageengans da auf da Zungan!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Schweinsbackerln musst du stundenlang bei niedriger Temperatur dünsten - dann zergehen sie dir auf der Zunge!', '[{"kategorie": "wörtlich", "text": "\"Schweinebäckchen muss man stundenlang bei niedriger Temperatur schmoren, bis sie auf der Zunge zergehen!\"  2. Um Schweinebäckchen perfekt zuzubereiten, sollten sie langsam bei niedriger Temperatur gegart werden - dann zergehen sie auf der Zunge!  3. Langsam und liebevoll geschmort, werden Schweinebäckchen zu einem zarten Hochgenuss, der auf der Zunge zergeht!"}]'::jsonb, ''),
  ('rindsbackaln-muassd-schdundnlaung-bei-niidriga-temparatua-dinstn-daunn-zageengans-da-auf-da-zungan', 'Rindsbackaln muassd schdundnlaung bei niidriga Temparatua dinstn - daunn zageengans da auf da Zungan!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Rindsbackerln musst du stundenlang bei niedriger Temperatur dünsten - dann zergehen sie dir auf der Zunge!', '[{"kategorie": "wörtlich", "text": "\"Rinderbäckchen muss man stundenlang bei niedriger Temperatur schmoren, bis sie auf der Zunge zergehen!\"  2. Um Rinderbäckchen perfekt zuzubereiten, sollten sie langsam bei niedriger Temperatur gegart werden - dann zergehen sie auf der Zunge!  3. Langsam und liebevoll geschmort, werden Rinderbäckchen zu einem zarten Hochgenuss, der auf der Zunge zergeht!"}]'::jsonb, ''),
  ('in-da-feinan-kuchl-san-fiaschbackaln-wiara-klaana-schotz-kaum-greessa-ois-a-daam-owa-voi-gschmackig', 'In da feinan Kuchl san Fiaschbackaln wiara klaana Schotz - kaum greessa ois a Daam, owa voi gschmackig!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'In der feinen Küche sind Fischbackerln wie ein kleiner Schatz – kaum größer als ein Daumen, aber voll schmackhaft!', '[{"kategorie": "wörtlich", "text": "\"Fischbäckchen sind ein Schatz der feinen Küche – kaum größer als ein Daumen, aber voller Geschmack!\"  2. Die Fischwangen gehören zu den feinsten Stücken der Küche – unscheinbar klein, aber geschmacklich ganz groß!  3. Das Wangenfleisch vom Fisch ist eine wahre Delikatesse – kaum daumengroß, aber voller Tiefe und Geschmack!"}]'::jsonb, ''),
  ('schweinswangaln-muassd-schdundnlaung-bei-niidriga-temparatua-dinstn-daunn-zageengans-da-auf-da-zungan', 'Schweinswangaln muassd schdundnlaung bei niidriga Temparatua dinstn - daunn zageengans da auf da Zungan!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Schweinswangerln musst du stundenlang bei niedriger Temperatur dünsten - dann zergehen sie dir auf der Zunge!', '[{"kategorie": "wörtlich", "text": "\"Schweinebäckchen muss man stundenlang bei niedriger Temperatur schmoren, bis sie auf der Zunge zergehen!\"  2. Um Schweinebäckchen perfekt zuzubereiten, sollten sie langsam bei niedriger Temperatur gegart werden - dann zergehen sie auf der Zunge!  3. Langsam und liebevoll geschmort, werden Schweinebäckchen zu einem zarten Hochgenuss, der auf der Zunge zergeht!"}]'::jsonb, ''),
  ('rindswangaln-muassd-schdundnlaung-bei-niidriga-temparatua-dinstn-daunn-zageengans-da-auf-da-zungan', 'Rindswangaln muassd schdundnlaung bei niidriga Temparatua dinstn - daunn zageengans da auf da Zungan!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Rindswangerln musst du stundenlang bei niedriger Temperatur dünsten - dann zergehen sie dir auf der Zunge!', '[{"kategorie": "wörtlich", "text": "\"Rinderbäckchen muss man stundenlang bei niedriger Temperatur schmoren, bis sie auf der Zunge zergehen!\"  2. Um Rinderbäckchen perfekt zuzubereiten, sollten sie langsam bei niedriger Temperatur gegart werden - dann zergehen sie auf der Zunge!  3. Langsam und liebevoll geschmort, werden Rinderbäckchen zu einem zarten Hochgenuss, der auf der Zunge zergeht!"}]'::jsonb, ''),
  ('in-da-feinan-kuchl-san-fiaschwangaln-wiara-klaana-schotz-kaum-greessa-ois-a-daam-owa-voi-gschmackig', 'In da feinan Kuchl san Fiaschwangaln wiara klaana Schotz - kaum greessa ois a Daam, owa voi gschmackig!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'In der feinen Küche sind Fischwangerln wie ein kleiner Schatz – kaum größer als ein Daumen, aber voll schmackhaft!', '[{"kategorie": "wörtlich", "text": "\"Fischwängchen sind ein Schatz der feinen Küche – kaum größer als ein Daumen, aber voller Geschmack!\"  2. Die Fischwangen gehören zu den feinsten Stücken der Küche – unscheinbar klein, aber geschmacklich ganz groß!  3. Das Wangenfleisch vom Fisch ist eine wahre Delikatesse – kaum daumengroß, aber voller Tiefe und Geschmack!"}]'::jsonb, ''),
  ('min-schuali-kaunnst-padoofaen-bis-da-da-saund-aus-de-uan-schdaubd-dea-bleibd-schdua-wia-beton', 'Min Schuali kaunnst padoofän, bis da da Saund aus de Uan schdaubd - dea bleibd schdua wia Beton!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit’m Schurli kannst du padofeln, bis dir der Sand aus den Ohren staubt – der bleibt stur wie Beton!', '[{"kategorie": "wörtlich", "text": "\"Mit dem Georg kannst du feilschen, bis dir der Sand aus den Ohren staubt – der bleibt stur wie Beton!\"  2. Mit dem Schurli kannst du verhandeln, bis dir die Zunge abfällt – der bleibt auf seinem Preis wie ein Ziegel auf’m Dach!  3. Mit dem  Georg brauchst du über keinen verhandeln – der ist beweglich wie ein Grabstein!"}]'::jsonb, ''),
  ('des-miass-ma-uns-no-auspadoofaen', 'Des miass ma uns no auspadoofän!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das müssen wir uns noch auspadofeln!', '[{"kategorie": "wörtlich", "text": "\"Darüber müssen wir noch verhandeln!\"  2. Das müssen wir noch in aller Ruhe ausverhandeln!  3. Da müssen wir uns noch zusammenreden!  4. Das müssen wir uns noch [[auskarteln]]!"}]'::jsonb, ''),
  ('droomad-aum-beag-bloosd-imma-a-koida-wind', 'Droomad aum Beag bloosd imma a koida Wind!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Droben am Berg bläst immer ein kalter Wind!', '[{"kategorie": "wörtlich", "text": "\"Oben auf dem Berg weht ständig ein kalter Wind!\"  2. Dort oben am Gipfel ist es immer zugig und kalt!  3. Hoch oben am Berg bläst dir der Wind die Seele aus dem Leib!"}]'::jsonb, ''),
  ('gee-ma-eine-ind-hittn-und-schau-ma-wos-drinnat-los-is', 'Gee ma eine ind Hittn und schau ma, wos drinnat los is!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Gehen wir rein in die Hütte und schau''n wir, was drinnert los ist!', '[{"kategorie": "wörtlich", "text": "\"Komm, wir gehen rein ins Lokal und schauen, was da drinnen abgeht!\"  2. Lass uns mal reinschauen, was da drinnen los ist!  3. Rein in die gute Stube und mal schauen, ob’s drinnen brennt oder brodelt!"}]'::jsonb, ''),
  ('jetzt-isa-drinnad', 'Jetzt isa drinnad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Jetzt ist er drinnert!', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"Jetzt ist er drin!\"  2. Jetzt ist er wirklich drinnen!  3. Jetzt ist der Ball endgültig im Tor!"}]'::jsonb, ''),
  ('drinnan-wiad-puudad-und-draussn-wiad-gsoffn-und-de-moral-hauma-haamgschickd', 'Drinnan wiad puudad und draussn wiad gsoffn - und de Moral hauma haamgschickd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Drinnen wird gepudert und draußen wird gesoffen - und die Moral haben wir heimgeschickt!', '[{"kategorie": "wörtlich", "text": "\"Drinnen wird gebumst, draußen läuft der Schnaps – und die Moral ist längst zur Tür raus!\"  2. Drinnen wird gevögelt und draußen läuft der Wein – und die Anstandshandschuhe haben wir zu Hause gelassen!  3. Drinnen lüstern, draußen lallen – und die Moral haben wir nach Hause geschickt!"}]'::jsonb, ''),
  ('drin-wia-draussd-da-oasch-bleibd-koid-waunnsd-ka-feia-host', 'Drin wia draussd - da Oasch bleibd koid, waunnsd ka Feia host!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Drinnen wie draußen - der Arsch bleibt kalt, wenn du kein Feuer hast!', '[{"kategorie": "wörtlich", "text": "\"Drinnen wie draußen – ohne Zunder friert dir der Arsch überall weg!\"  2. Egal ob drinnen oder draußen – wenn’s in dir nicht lodert, wirst du vom Frost des Lebens gefressen!  3. Ob drinnen im Haus oder draußen unter freiem Himmel – wo keine innere Glut ist, friert die Seele!"}]'::jsonb, ''),
  ('marantana-dea-is-uandlich-drinnad', 'Marantana, dea is uandlich drinnad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Oh heilige Maria und Anna - der ist ordentlich drinnen!', '[{"kategorie": "wörtlich", "text": "\"Oh heilige Maria und Anna - der sitzt aber gehörig in der Patsche!\"  2. Heiliger Bimbam, der hat sich ganz schön reingeritten!  3. Du meine Güte, der hockt fett in der Scheiße!"}]'::jsonb, ''),
  ('imma-schee-pomale', 'Imma schee pomale!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Immer schön pomali!', '[{"kategorie": "wörtlich", "text": "\"Immer schön langsam!\"  2. \"Nur nichts überstürzen!\"  3. Immer mit der Ruhe!"}]'::jsonb, ''),
  ('buama-wia-gengans-gaunz-pomale-au', 'Buama, wia gengans gaunz pomale au!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Buben, wir gehen''s ganz pomali an!', '[{"kategorie": "wörtlich", "text": "\"Jungs, wir gehen es ganz entspannt an!\"  2. \"Männer, wir gehen''s mal in aller Ruhe an!\"  3. \"Jungs, wir gehen''s ganz gemütlich an!\""}]'::jsonb, ''),
  ('nimm-dar-an-poppndeckl-zum-untaleeng', 'Nimm dar an Poppndeckl zum Untaleeng!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Nimm dir einen Pappendeckel zum Unterlegen!', '[{"kategorie": "wörtlich", "text": "\"Nimm dir einen Pappdeckel zum Unterlegen!\"  2. \"Hol dir ''nen Kartonstreifen zum Unterlegen!\"  3. \"Nimm dir einen Kartondeckel zum Drunterlegen!\""}]'::jsonb, ''),
  ('wia-baun-des-ding-mit-dem-wos-ma-haum-boppadeckl-kaawaebinda-eisana-wueuen', 'Wia baun des Ding mit dem, wos ma haum - Boppadeckl, Kaawäbinda, eisana Wüün!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wir bauen das Ding mit dem, was wir haben – Pappendeckel, Kabelbinder, eiserner Wille!', '[{"kategorie": "wörtlich", "text": "\"Wir bauen das Ding mit dem, was da ist – Pappdeckel, Kabelbinder, eiserner Wille!\"  2. \"Wir bauen mit dem, was greifbar ist – Pappe, Kabelbinder und ''ne große Portion Sturheit! MacGyver wäre stolz auf uns!\"  3. Gebt mir Pappdeckel, Kabelbinder und einen Hammer – und ich bau euch ein Weltwunder!"}]'::jsonb, ''),
  ('i-hob-mei-gaunze-woonung-in-drei-poppndecklkistn-gschdopfd-des-nennt-ma-daunn-woi-mobueues-oeoelend', 'I hob mei gaunze Woonung in drei Poppndecklkistn gschdopfd - des nennt ma daunn woi ''mobüüs Öölend''!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich hab meine ganze Wohnung in drei Pappendeckelkisten gestopft – das nennt man dann wohl mobiles Elend!', '[{"kategorie": "wörtlich", "text": "\"Ich hab meine ganze Wohnung in drei Pappkartons gestopft – das nennt man dann wohl mobiles Elend!\"  2. Ich hab mein ganzes Leben auf drei Kartonkisten verteilt – je 30 mal 40 Zentimeter Wellpappe!  3. Drei Pappendeckelkisten und ein Haufen Chaos – das ist jetzt mein Leben zum Mitnehmen!"}]'::jsonb, ''),
  ('dassd-fias-hackln-gschdrofd-wiasd-und-fias-nixtuan-beloond-is-mea-ois-bresant', 'Dassd fias Hackln gschdrofd wiasd und fias Nixtuan beloond, is mea ois bresant!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dass du fürs Hackeln bestraft wirst und fürs Nichtstun belohnt, ist mehr als brisant!', '[{"kategorie": "wörtlich", "text": "\"Dass man fürs Arbeiten bestraft wird und fürs Nichtstun belohnt, ist ein mehr als brisantes Thema!\"  2. Wir haben ein System, in dem Ehrliche die Dummen sind – das ist brisanter als jede Schlagzeile!  3. Leistung lohnt sich nicht mehr – und das ist das eigentlich brennende Problem!"}]'::jsonb, ''),
  ('dea-is-heid-owa-bresi', 'Dea is heid owa bresi!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist heute aber bresi!', '[{"kategorie": "wörtlich", "text": "\"Der ist heute geladen bis zum Anschlag!\"  2. \"Der hat heute die Zündschnur kurz wie nie!\"  3. \"Der ist heute ganz auf Krawall gebürstet!\""}]'::jsonb, ''),
  ('dass-dea-de-oide-vom-schaeaef-puudad-is-a-weng-bresi', 'Dass dea de Oide vom Schääf puudad, is a weng bresi!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dass der die Alte vom Chef pudert, ist ein wenig ''bresi''!', '[{"kategorie": "wörtlich", "text": "\"Dass der die Alte vom Chef vögelt, ist ein wenig brisant!\"  2. Dass der die Frau vom Chef nagelt, ist schon Zündstoff pur!  3. Der bumst die Frau vom Chef – das ist mehr als gewagt!"}]'::jsonb, ''),
  ('moch-mi-ned-bresant', 'Moch mi ned bresant!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mach mich nicht brisant!', '[{"kategorie": "wörtlich", "text": "\"Mach mich nicht wütend!\"  2. \"Bring mich nicht in Rage!\"  3. \"Bring mich nicht auf die Palme!\""}]'::jsonb, ''),
  ('des-mochd-mi-bresant', 'Des mochd mi bresant!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das macht mich brisant!', '[{"kategorie": "wörtlich", "text": "\"Das macht mich wütend!\"  2. \"Das bringt mich in Rage!\"  3. \"Da werd ich fuchsteufelswild!\"  4. \"Das bringt mich auf die Palme!\""}]'::jsonb, ''),
  ('bresant-gee', 'bresant gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'bresant gehen', '[{"kategorie": "wörtlich", "text": "\"wütend werden\""}, {"kategorie": "", "text": "\"in Rage kommen\""}, {"kategorie": "", "text": "\"in Wut geraten\""}, {"kategorie": "", "text": "\"die Beherrschung verlieren\""}, {"kategorie": "", "text": "\"vor Wut hochgehen\""}]'::jsonb, 'Wau mi wea auliagd, daunn gee I bresant!'),
  ('wau-mi-wea-auliagd-daunn-gee-i-bresant', 'Wau mi wea auliagd, daunn gee I bresant!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn mich wer anlügt, dann geh ich bresant!', '[{"kategorie": "wörtlich", "text": "\"Wenn mich wer anlügt, dann raste ich aus!\"  2. Wenn mich wer anlügt, dann verliere ich die Beherrschung!  3. Wenn mich wer anlügt, brennt bei mir die Sicherung durch!"}]'::jsonb, 'bresant gee'),
  ('si-putzn', 'si putzn', '', '', '', 'Grundwortschatz Wienerisch', 'sich putzen', '[{"kategorie": "wörtlich", "text": "\"sich aus dem Staub machen\" (vom mittelhochdeutschen \"butzen\"=\"saubermachen\")"}, {"kategorie": "fig.", "text": "verschwinden, abhauen, sich verziehen, sich vom Acker machen, [[an]] Schuach mochn"}]'::jsonb, 'Putz di, solaungsd no zwa Haxn hosd!'),
  ('putz-di-solaungsd-no-zwa-haxn-hosd', 'Putz di, solaungsd no zwa Haxn hosd!', '', '', '', 'Wiener Gaunersprache', 'Putz dich, solange du noch zwei Haxen hast!', '[{"kategorie": "wörtlich", "text": "\"Mach dich vom Acker, solange du noch zwei Beine hast!\"  2. \"Verzieh dich, solange du noch gehen kannst!\"  3. \"Zieh Leine, solange du noch geradeaus laufen kannst!\""}]'::jsonb, 'si putzn'),
  ('heast-oida-des-is-jo-ua-oag', 'Heast Oida, des is jo ua-oag!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Hey, Alter, das ist ja ur-arg!', '[{"kategorie": "wörtlich", "text": "\"Boah, krass, Alter!\"  2. \"Digga, das ist ja voll krank!\"  3. \"Bro, das ist echt [[cringe]]!\""}]'::jsonb, ''),
  ('dass-eam-aafoch-goosted-haum-is-echt-oag', 'Dass eam aafoch goosted haum, is echt oag!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Dass sie ihn einfach geghostet haben, ist echt arg!', '[{"kategorie": "wörtlich", "text": "\"Dass sie ihn einfach geghostet haben, ist echt krank!\"  2. Den einfach so fallen zu lassen, ohne Erklärung – das ist echt übel!  3. Bro, die haben ihn gelöscht wie ''ne Spam-Mail – wie eiskalt ist das denn?!"}]'::jsonb, ''),
  ('dea-schaud-oag-zaprackd-aus', 'Dea schaud oag zaprackd aus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der sieht arg zerprackt aus!', '[{"kategorie": "wörtlich", "text": "\"Der sieht arg mitgenommen aus!\"  2. \"Der sieht übel zugerichtet aus!\"  3. \"Der sieht ganz schön gerädert aus!\""}]'::jsonb, ''),
  ('ua-oag', 'ua-oag', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'urarg', '[{"kategorie": "wörtlich", "text": "\"urarg\" (Kompositum aus dem Intensivpräfix \"ur\"=\"total\" und [[arg]]=\"heftig\")"}, {"kategorie": "allg.", "text": "\"extrem arg\", \"wirklich schlimm\", \"brutal heftig\", \"echt mies\", \"total daneben\""}]'::jsonb, 'Heast Oida, des is jo ua-oag!'),
  ('des-is-ua-oag-dass-di-ghoosted-haum', 'Des is ua-oag, dass di ghoosted haum!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das ist urarg, dass sie dich geghostet haben!', '[{"kategorie": "wörtlich", "text": "\"Das ist echt mies, dass sie dich geghostet haben!\"  2. \"Das ist wirklich schlimm, dass sie den Kontakt einfach abgebrochen haben, ohne ihm ein Wort zu sagen!\"  3. \"Das ist total daneben, dass sie ihn komplett auf stumm geschaltet haben!\""}]'::jsonb, ''),
  ('ua', 'ua-', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'ur-', '[{"kategorie": "wörtlich", "text": "\"ur-\" (verstärkendes Präfix vor Eigenschaftswörtern)"}, {"kategorie": "Jugendsprache", "text": "sehr, extrem, besonders, mega-…, hyper-…, voll…, super-…"}]'::jsonb, ''),
  ('des-neiche-raadl-is-ualeiwaund-foad-si-wiara-woeoedwunda', 'Des neiche Raadl is ualeiwaund - foad si wiara Wöödwunda!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das neue Radl ist urleiwand – fährt sich wie ein Weltwunder!', '[{"kategorie": "wörtlich", "text": "\"Das neue Fahrrad ist urgeil – rennt wie ''ne Rakete!\"  2. \"Megakrass, wie das Rad abgeht – fühlt sich an wie fliegen!\"  3. Das Rad ist einfach nur [[next]] level – ''smooth as hell''!\""}]'::jsonb, ''),
  ('des-essn-woar-uaguad-i-kenntad-mi-eigroobm', 'Des Essn woar uaguad - I kenntad mi eigroobm!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das Essen war urgut - ich könnte mich eingraben!', '[{"kategorie": "wörtlich", "text": "\"Das Essen war megafein - ich könnt rollen, so gut war das!\"  2. \"Das Essen war hammergeil - ich bin foodtechnisch im Himmel!\"  3. \"Das Essen war superlecker - war jede Gabel wert!\""}]'::jsonb, ''),
  ('de-mathe-schui-oaweid-woar-uaschlimm-i-hob-fost-nix-tscheckd', 'De Mathe-Schui-Oaweid woar uaschlimm - I hob fost nix tscheckd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Die Mathe-Schularbeit war ur­schlimm – ich hab fast nichts gecheckt!', '[{"kategorie": "wörtlich", "text": "\"Die Mathematik-Schularbeit war extrem arg – ich hab fast nichts kapiert!\"  2. Die Mathe-Schularbeit war voll krass – ich hätt genauso gut ''nen Einkaufszettel abgeben können!  3. Die Schularbeit war komplett [[lost]] – ich hab null gerafft!"}]'::jsonb, ''),
  ('latein-leana-is-uazaach-do-bleibd-nix-pickn', 'Latein leana is uazaach - do bleibd nix pickn!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Latein lernen ist urzäh - da bleibt nichts picken!', '[{"kategorie": "wörtlich", "text": "\"Latein lernen fällt mir extrem schwer – ich kann mir kaum etwas merken!\"  2. Latein ist unglaublich mühsam – bei mir bleibt nichts im Kopf!  3. Latein ist todesschwer, Mann – ich merk mir null!"}]'::jsonb, ''),
  ('des-maetsch-woa-uazaach-zum-auschaun', 'Des Mätsch woa uazaach zum Auschaun!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Das Match war urzäh zum Anschauen!', '[{"kategorie": "wörtlich", "text": "\"Das Match war urfad zum Anschauen!\"  2. Das Match war slow-motion in Echtzeit – voll zum Einschlafen!  3. Das Spiel hat sich hingezogen wie ein Kaugummi - voll öd!"}]'::jsonb, ''),
  ('mia-is-heit-uafaad-kaa-plan-wos-i-mochn-soi', 'Mia is heit uafaad - kaa Plan, wos I mochn soi!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Mir is heute urfad – kein Plan, was ich machen soll!', '[{"kategorie": "wörtlich", "text": "\"Mir ist todeslangweilig heute - kein Plan, was ich tun könnte!\"  2. \"Voll öd - ich weiß heute echt nicht, was ich mit mir anfangen soll!\"  3. Bro, mir ist so fad, ich überleg, ob ich lernen soll – just for fun!"}]'::jsonb, ''),
  ('du-bist-uadeppad-owa-i-mog-di-trotzdem', 'Du bist uadeppad - owa I mog di trotzdem!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Du bist urdeppert – aber ich mag dich trotzdem!', '[{"kategorie": "wörtlich", "text": "\"Du bist komplett gaga – aber ich mag dich trotzdem!\"  2. Du bist voll durchgeknallt – aber ich hab dich trotzdem lieb!  3. Du bist komplett lost – aber irgendwie find ich dich süß!"}]'::jsonb, ''),
  ('des-maetsch-is-uadeppad-glaufn-eigntoa-oeoefa-und-a-roode', 'Des Mätsch is uadeppad glaufn - Eigntoa, Ööfa und a Roode!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Das Match ist urdeppert gelaufen - Eigentor, Elfer und eine Rote!', '[{"kategorie": "wörtlich", "text": "\"Das Match ist total unglücklich verlaufen - zuerst Eigentor, dann Elfer, und dann fliegt auch noch einer vom Platz!\"  2. Eigentor, Elfer, rote Karte – blöder hätt''s nicht laufen können!  3. Das Spiel ist saublöd verlaufen - Eigentor, Elfmeter und am Schluss auch noch ein Platzverweis!"}]'::jsonb, ''),
  ('du-schausd-heit-uaschee-aus-i-maans-eanst', 'Du schausd heit uaschee aus - I maans eanst!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Du schaust heute urschön aus - ich mein''s ernst!', '[{"kategorie": "wörtlich", "text": "\"Du siehst heute einfach wunderschön aus – das mein ich ganz ernst!\"  2. \"Du schaust heut [[urleiwand]] aus – ganz ehrlich!\"  3. Wow, heute bist du echt ’n Glow-Up auf zwei Beinen – no joke!"}]'::jsonb, ''),
  ('wau-uaschee-heit-bist-a-echta-gloo-ap-auf-zwa-haxn-kaa-schbaass', 'Wau, uaschee - heit bist a echta Gloo-Ap auf zwa Haxn - kaa Schbaass!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Wow, urschön - heut'' bist ein echter Glow-Up auf zwei Haxen - kein Spaß!', '[{"kategorie": "wörtlich", "text": "\"Wow, wunderschön - heut'' bist ein echter Glow-Up auf zwei Beinen - no joke!\"  2. Wow, heute siehst du aus wie ein Kunstwerk – und ich mein’s ernst, nicht nur als Kompliment!  3. Du bist heut ein richtiger Hingucker – ich glaub, ich brauch ''ne Sonnenbrille, no joke!"}]'::jsonb, ''),
  ('gloo-ap', 'Gloo-Ap!', 'der', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Glow-up', '[{"kategorie": "wörtlich, Jugendsprache", "text": "\"Glow-Up\" (vom englischen \"to glow up\"=\"sichtbar schöner werden“)"}, {"kategorie": "allg.", "text": "\"auffällige, positive Veränderung\" (vor allem im Aussehen, aber auch im Selbstbewusstsein oder Lebensstil), \"Verwandlung zum Positiven\", \"Upgrade\", \"Hingucker\""}]'::jsonb, ''),
  ('no-dschook', 'No Dschook!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'No joke!', '[{"kategorie": "wörtlich", "text": "\"No joke!\" (vom englischen \"No joke!\" =  \"kein Spaß!\")"}, {"kategorie": "Jugendsprache", "text": "\"Kein Witz!\"  3. \"Ich meine das ernst!\"  4. \"Das ist kein Spaß!\"  5. [[Real Talk!]]  6. [[Kaa]] Schmää!   8. [[Kaa]] Füüm!"}]'::jsonb, 'Du bist heit mega neiss - I häu glei, no Dschook!'),
  ('du-bist-heit-mega-neiss-i-haeu-glei-no-dschook', 'Du bist heit mega neiss - I häu glei, no Dschook!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Du bist heute mega nice - ich heul gleich, no joke!', '[{"kategorie": "wörtlich", "text": "\"Du schaust heute urschön aus - ich heul gleich, wirklich!\"  2. Du bist heut [[literally]] zu schön fürs echte Leben – kein Schmäh!  3. Heut bist du so [[cute]], das gehört verboten – kein Witz!"}]'::jsonb, ''),
  ('i-bin-litaraelly-aum-schdeam', 'I bin litarälly aum Schdeam!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ich bin literally am Sterben!', '[{"kategorie": "wörtlich, Jugendsprache", "text": "\"Ich bin buchstäblich am Sterben!\"  2. Ich bin echt am Ende - kein Schmäh!  3. Ich pack''s gar nicht mehr, [[legit]]!"}]'::jsonb, ''),
  ('daunk-da-bro-des-woa-uasuupa-von-dia', 'Daunk da, Bro - des woa uasuupa von dia!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Danke dir, Bruder - das war ursuper von dir!', '[{"kategorie": "wörtlich", "text": "\"Bruder, danke nochmal - das war megacool von dir!\"  2. Vielen lieben Dank, Bruder – das war wirklich großartig von dir!  3. Ehrenaktion – danke, Bruder!"}]'::jsonb, ''),
  ('i-finds-uableed-dass-i-grod-nix-zum-schnacksln-hob', 'I finds uableed, dass I grod nix zum Schnacksln hob!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ich find''s urblöd, dass ich grad nichts zum Schnackseln habe!', '[{"kategorie": "wörtlich", "text": "\"Ich find''s blöd hoch zehn, dass ich grad keine/n zum Vögeln hab!\"  2. Es ist jammerschade, dass ich grad niemanden fürs Bett habe!  3. Es ist wirklich zu blöd, dass bei mir grad tote Hose ist!"}]'::jsonb, ''),
  ('i-finds-uadeppad-dass-i-grod-nix-zum-schnacksln-hob', 'I finds uadeppad, dass I grod nix zum Schnacksln hob!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich find''s urdeppert, dass ich grad nichts zum Schnackseln habe!', '[{"kategorie": "wörtlich", "text": "\"Ich find''s blöd hoch zehn, dass ich grad keine/n zum Vögeln hab!\"  2. Es ist jammerschade, dass ich grad niemanden fürs Bett habe!  3. Es ist wirklich zu blöd, dass bei mir grad tote Hose ist!"}]'::jsonb, ''),
  ('de-klaane-is-uableed-owa-im-bett-is-a-echte-gronoodn', 'De Klaane is uableed, owa im Bett is a echte Gronoodn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Kleine ist urblöd, aber im Bett ist sie ''ne echte Granate!', '[{"kategorie": "wörtlich", "text": "\"Sie ist strunzdumm, aber im Bett eine absolute Wucht!\"  2. Das Mädel ist zwar total bescheuert, aber im Bett ist sie der absolute Hammer!  3. Bei der Kleinen ist unterm Pony ist nicht viel los, aber unterm Bettzeug dafür umso mehr!"}]'::jsonb, ''),
  ('des-konzeat-gestan-woar-uageil-i-hob-no-nii-so-a-schdimmung-daleebd', 'Des Konzeat gestan woar uageil - I hob no nii so a Schdimmung daleebd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das Konzert gestern war urgeil - ich hab noch nie so ''ne Stimmung erlebt!', '[{"kategorie": "wörtlich", "text": "\"Das Konzert gestern war der Hammer – so eine Stimmung hab ich noch nie erlebt!\"  2. Das Konzert war mega fett gestern – ich war total [[geflasht]]!  3. Alter, das Konzert gestern war einfach nur krass – ich hab sowas noch nie erlebt, Gänsehaut pur!"}]'::jsonb, ''),
  ('zeaschd-woas-ualiab-zu-mia-owa-jetzt-is-auf-amoi-ua-oasch-wuan', 'Zeaschd woas ualiab zu mia - owa jetzt is auf amoi ua-oasch wuan!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Zuerst war sie urlieb zu mir - aber jetzt ist sie auf einmal urarsch geworden!', '[{"kategorie": "wörtlich", "text": "\"Zuerst war sie supernett zu mir - aber jetzt ist aus ihr ein richtiges Arschloch geworden!\"  2. \"Am Anfang war sie megasüß – und jetzt? Voll die Giftschlange!\"  3. Sie war zuerst total goldig zu mir – und jetzt benimmt sie sich wie das letzte Arschloch!"}]'::jsonb, ''),
  ('ua-oasch', 'ua-oasch', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'urarsch', '[{"kategorie": "wörtlich", "text": "\"urarsch\" (Kompositum aus dem Intensivpräfix \"ur\"=\"mega\" und \"arsch\"=\"beschissen\")"}, {"kategorie": "Jugendsprache", "text": "\"voll scheiße\", \"total beschissen\", \"echt mies\", \"Bullshit hoch zehn\""}]'::jsonb, 'Des is echt ua-oasch!'),
  ('des-is-ua-oasch-von-dia-dassd-mi-grod-jetzt-so-haenga-lossd', 'Des is ua-oasch von dia, dassd mi grod jetzt so hänga lossd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das ist urarsch von dir, dass du mich grad jetzt so hängen lässt!', '[{"kategorie": "wörtlich", "text": "\"Das ist echt mies von dir, dass du mich ausgerechnet jetzt im Stich lässt!\"  2. Bro, das ist voll scheiße von dir – lässt mich im schlimmsten Moment alleine!  3. So ein Arsch-Move von dir, Bruder – mich jetzt einfach so hängen zu lassen!"}]'::jsonb, ''),
  ('des-is-echt-ua-oasch', 'Des is echt ua-oasch!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das ist echt urarsch!', '[{"kategorie": "wörtlich", "text": "\"Das ist echt voll scheiße!\"  2. Das ist wirklich total beschissen!  3. Das ist Bullshit hoch zehn!"}]'::jsonb, ''),
  ('da-wiat-is-heit-ua-oasch-drauf-dea-mochd-an-jeedn-zua-sau', 'Da Wiat is heit ua-oasch drauf - dea mochd an jeedn zua Sau!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Wirt ist heut urarsch drauf - der macht einen jeden zur Sau!', '[{"kategorie": "wörtlich", "text": "\"Der Wirt ist heute voll scheiße drauf – der macht einen jeden zur Sau!\"  2. Der Wirt führt sich heute total beschissen auf - lässt seine miese Laune an den Gästen aus!  3. Der Wirt ist heute komplett [[aggro]] - macht jeden nieder, der bei der Tür reinkommnt!"}]'::jsonb, ''),
  ('des-is-bullschitt-hoch-zeen', 'Des is Bullschitt hoch zeen!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das ist Bullshit hoch zehn!', '[{"kategorie": "wörtlich", "text": "\"Das ist total beschissen!\"  2. \"Das ist komplette Scheiße!\"  3. \"Das ist echt urarsch!\""}]'::jsonb, ''),
  ('voi-rodscha', 'Voi rodscha!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Voll Roger!', '[{"kategorie": "wörtlich", "text": "\"Voll Roger!\" (Ausdruck aus dem Funksprech für \"Alles bestens!\")"}, {"kategorie": "allg.", "text": "Passt!  3. Geht klar!  4. Bin dabei!  5. [[Okidoki]]!  6. [[Tippitoppi]]!"}]'::jsonb, 'Du bringsd de Fressalien mit und I de Trangln - voi rodscha!'),
  ('du-bringsd-de-fressalien-mit-und-i-de-trangln-voi-rodscha', 'Du bringsd de Fressalien mit und I de Trangln - voi rodscha!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Du bringst die Fressalien mit und ich die Getränke - voll roger!', '[{"kategorie": "wörtlich", "text": "\"Du bringst was zu essen mit, und ich die Getränke - geht klar!\"  2. Du kümmerst dich ums Essen, ich nehm die Drinks mit – passt!  3. Food kommt von dir, Drinks von mir – voll roger!"}]'::jsonb, ''),
  ('todes', 'todes-', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'todes-', '[{"kategorie": "wörtlich", "text": "\"todes-\" (Jugendsprache, verstärkendes Präfix vor Eigenschaftswörtern)"}, {"kategorie": "allg.", "text": "sehr, extrem, besonders, mega-…, hyper-…, voll…, super-…"}]'::jsonb, ''),
  ('sei-autfit-woa-todesfresch-direkt-ausm-lukbuk', 'Sei Autfit woa todesfresch - direkt ausm Lukbuk!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Sein Outfit war todesfresh – direkt aus’m Lookbook!', '[{"kategorie": "wörtlich", "text": "\"Sein Outfit war megastylisch – wie aus einem Modemagazin!\"  2. Sein Look war modisch, frisch und total stimmig - wie aus dem Bilderbuch!  3. Er war super angezogen – sah aus, als käme er direkt vom Laufsteg!"}]'::jsonb, ''),
  ('ea-hod-sei-leebdooch-no-ned-ghackld', 'Ea hod sei Leebdooch no ned ghackld!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat sein Lebtag noch nicht gehackelt!', '[{"kategorie": "wörtlich", "text": "\"Er hat Zeit seines Lebens noch nie gearbeitet!\"  2. \"Er ist sein ganzes Leben lang arbeitslos gewesen!\"  3. \"Er ist Zeit seines Lebens noch nie einer geregelten Beschäftigung nachgegangen!\""}]'::jsonb, ''),
  ('so-a-blaeaede-funsn-hob-i-mei-leebdooch-no-ned-gseeng', 'So a blääde Funsn hob I mei Leebdooch no ned gseeng!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'So eine blöde Funs''n hab ich mein Lebtag noch nicht gesehen!', '[{"kategorie": "wörtlich", "text": "\"So eine dumme Zicke habe ich mein Leben lang noch nie gesehen!\"  2. So einem Trampel bin ich in meinem ganzen Leben noch nie begegnet!  3. Zeit meines Lebens ist mir eine so blöde Zimtzicke noch nie über den Weg gelaufen!"}]'::jsonb, ''),
  ('a-leebdooch-laung', 'a Leebdooch laung', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Lebtag lang', '[{"kategorie": "wörtlich", "text": "\"ein Leben lang\""}, {"kategorie": "", "text": "\"zeitlebens\""}, {"kategorie": "", "text": "\"lebenslang\""}, {"kategorie": "", "text": "\"die ganze Lebenszeit über\""}]'::jsonb, 'Maunche Freindschoftn hoidn a Leebdooch laung!'),
  ('maunche-freindschoftn-hoidn-a-leebdooch-laung', 'Maunche Freindschoftn hoidn a Leebdooch laung!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Manche Freundschaften halten ein Lebtag lang!', '[{"kategorie": "wörtlich", "text": "\"Manche Freundschaften halten ein Leben lang!\"  2. Es gibt Freundschaften, die ein ganzes Leben überdauern!  3. Was man von Herzen gern hat, das hält ein Leben lang!"}]'::jsonb, 'a Leebdooch laung'),
  ('beim-wiatn-is-a-schdimmung-wias-a-leebdoch-no-ned-woa', 'Beim Wiatn is a Schdimmung, wias a Leebdoch no ned woa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Beim Wirten ist eine Stimmung, wie sie ein Lebtag noch nicht war!', '[{"kategorie": "wörtlich", "text": "\"Beim Wirten herrscht eine Stimmung, wie man sie zeitlebens noch nie gesehen hat!\"  2. So eine Atmosphäre hat man beim Wirt in seinem ganzen Leben noch nicht gesehen!  3. Beim Wirt geht’s grad ab wie noch nie – sowas hast du dein ganzes Leben nicht gesehen!"}]'::jsonb, ''),
  ('liawa-oam-drau-ois-oam-ob', 'Liawa oam drau ois Oam ob!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Lieber arm dran als Arm ab!', '[{"kategorie": "wörtlich, Wortspiel", "text": "\"Besser pleite als tot!\"  2. Lieber schlecht drauf als gar nicht mehr da!  3. Armut ist hart – aber nicht das Ende der Welt!"}]'::jsonb, ''),
  ('a-oams-wiaschdl', 'a oams Wiaschdl', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein armes Würstel', '[{"kategorie": "wörtlich", "text": "\"ein bedauernswertes Geschöpf\""}, {"kategorie": "", "text": "\"ein armer Tropf\""}, {"kategorie": "", "text": "\"ein Häufchen Elend\""}, {"kategorie": "", "text": "\"ein armer Teufel\""}, {"kategorie": "", "text": "[[a oame Haut]]"}, {"kategorie": "", "text": "[[a oame Söö]]"}, {"kategorie": "", "text": "[[a oama Schlucka]]"}]'::jsonb, 'Dea is so lost - a oams Wiaschdl auf Schdaundgas!'),
  ('dea-is-so-lost-a-oams-wiaschdl-auf-schdaundgas', 'Dea is so lost - a oams Wiaschdl auf Schdaundgas!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Der ist so lost – ein armes Würstel auf Standgas!', '[{"kategorie": "wörtlich, Jugendsprache", "text": "\"Der steht völlig neben sich – ein armes Würstel ohne jeden Antrieb!\"  2. Er ist völlig neben der Spur – ein armer Kerl, der sein Leben lang auf der Stelle tritt!  3. Er steht da wie ein Häufchen Elend und kommt keinen Schritt weiter!"}]'::jsonb, 'a oams Wiaschdl'),
  ('auf-schdaundgas', 'auf Schdaundgas', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf Standgas', '[{"kategorie": "wörtlich", "text": "\"im Leerlauf\""}, {"kategorie": "fig.", "text": "antriebslos, träge, auf der Stelle tretend"}, {"kategorie": "Fußballerjargon", "text": "\"auf Sparflamme\", \"im Schlafwagenmodus\", \"ohne jeden Einsatz\""}]'::jsonb, 'Du kaunnsd kan Punkt hoin, waunn de hoibe Maunnschoft auf Schdaundgas kickd!'),
  ('du-kaunnsd-kan-punkt-hoin-waunn-de-hoibe-maunnschoft-auf-schdaundgas-kickd', 'Du kaunnsd kan Punkt hoin, waunn de hoibe Maunnschoft auf Schdaundgas kickd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Du kannst keinen Punkt holen, wenn die halbe Mannschaft auf Standgas kickt!', '[{"kategorie": "wörtlich", "text": "\"Du kannst keinen Punkt holen, wenn die halbe Mannschaft auf Sparflamme kickt!\"  2. Mit der halben Truppe im Leerlauf brauchst du auf Punkte erst gar nicht zu hoffen!  3. Wenn alle pimmeln statt pressen, kanst du dir die Punkte gleich abschminken!"}]'::jsonb, 'auf Schdaundgas'),
  ('a-oama-schlucka', 'a oama Schlucka', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein armer Schlucker', '[{"kategorie": "wörtlich", "text": "\"ein bedauernswertes Geschöpf\""}, {"kategorie": "", "text": "\"ein armer Tropf\""}, {"kategorie": "", "text": "\"ein Häufchen Elend\""}, {"kategorie": "", "text": "\"ein armer Teufel\""}, {"kategorie": "", "text": "[[a oame Haut]]"}, {"kategorie": "", "text": "[[a oame Söö]]"}, {"kategorie": "", "text": "[[a oams Wiaschdl]]"}]'::jsonb, 'a oams Wiaschdl'),
  ('ea-woa-sei-leebdooch-laung-a-oama-schlucka-owa-nii-unglicklich', 'Ea woa sei Leebdooch laung a oama Schlucka - owa nii unglicklich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er war sein Leben lang ein armer Schlucker, aber nie unglücklich!', '[{"kategorie": "wörtlich", "text": "\"Er war zeitlebens ein armer Hund, aber nie unglücklich!\"  2. Er ist zwar chronisch pleite, aber nie mies drauf!  3. Er hatte sein Leben lang nie viel Geld - aber trotzdem ist er glücjlich und zufrieden!"}]'::jsonb, 'a oama Schlucka'),
  ('a-oame-haut', 'a oame Haut', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine arme Haut', '[{"kategorie": "wörtlich", "text": "\"ein bedauernswertes Geschöpf\""}, {"kategorie": "", "text": "\"ein armer Tropf\""}, {"kategorie": "", "text": "\"ein Häufchen Elend\""}, {"kategorie": "", "text": "\"ein armer Teufel\""}, {"kategorie": "", "text": "[[a oame Schlucka]]"}, {"kategorie": "", "text": "[[a oame Söö]]"}, {"kategorie": "", "text": "[[a oams Wiaschdl]]"}]'::jsonb, 'a oams Wiaschdl'),
  ('so-a-oame-haut-wia-dea-ziagds-pech-magisch-au', 'So a oame Haut wia dea ziagds Pech magisch au!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So eine arme Haut wie der zieht das Pech magisch an!', '[{"kategorie": "wörtlich", "text": "\"Ein armer Tropf wie er scheint das Unglück regelrecht anzuziehen!\"  2. Ein armer Teufel wie er hat das Pech wohl abonniert!  3. Bei diesem armen Kerl geht wirklich alles schief, was schiefgehen kann!"}]'::jsonb, 'a oame Haut'),
  ('a-oame-soeoe', 'a oame Söö', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine arme Seele', '[{"kategorie": "wörtlich", "text": "\"ein bedauernswertes Geschöpf\""}, {"kategorie": "", "text": "\"ein armer Tropf\""}, {"kategorie": "", "text": "\"ein Häufchen Elend\""}, {"kategorie": "", "text": "\"ein armer Teufel\""}, {"kategorie": "", "text": "[[a oame Schlucka]]"}, {"kategorie": "", "text": "[[a oame Haut]]"}, {"kategorie": "", "text": "[[a oams Wiaschdl]]"}]'::jsonb, 'a oams Wiaschdl'),
  ('auf-dass-de-oame-soeoe-endlich-ia-rua-hod', 'Auf dass de oame Söö endlich ia Rua hod!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Auf dass die arme Seele endlich ihre Ruhe hat!', '[{"kategorie": "wörtlich", "text": "\"Auf dass die geplagte Seele endlich ihren Frieden findet!\"  2. Auf dass dieser arme Tropf endlich zur Ruhe kommt!  3. Möge der arme Kerl doch endlich seinen Frieden haben!"}]'::jsonb, 'a oame Söö'),
  ('wiaschdlsiada-san-wia-beichtvaeaeta-si-hean-ollas-wissen-ollas-und-aum-schluss-geebms-aa-no-eanan-senf-dazua', 'Wiaschdlsiada san wia Beichtvääta - si hean ollas, wissen ollas, und aum Schluss geebms aa no eanan Senf dazua!', '', '', '', 'Wiener Würstelstandjargon', 'Würstelsieder sind wie Beichtväter - sie hören alles, wissen alles, und am Schluss geben sie auch noch ihren Senf dazu!', '[{"kategorie": "wörtlich", "text": "\"Würstelmänner sind wie Priester im Schürzl – sie hören zu, wissen alles und geben am Ende auch noch ihren Senf dazu!\"  2. Der Würstelsieder ist wie ein Pfarrer mit Grillzange – er hört dir zu, weiß mehr über dich als du selber, und zum Schluss drückt er auch noch seinen Senf drauf, ob du willst oder nicht!  3. Würstelsieder reden wenig, wissen alles – und servieren dir am Schluss a g''salzene Wahrheit mit scharfem Senf!"}]'::jsonb, ''),
  ('oida-das-wiaschdl-woa-so-haass-i-hob-ma-fost-de-goschn-vabrennd', 'Oida, das Wiaschdl woa so haass, i hob ma fost de Goschn vabrennd!', '', '', '', 'Wiener Würstelstandjargon', 'Alter, das Würstel war so heiß, ich habe mir fast die Gosch''n verbrannt!', '[{"kategorie": "wörtlich", "text": "\"Alter, das Würstchen war brennheiß, ich hab mir fast das Maul verbrannt!\"  2. Mann, das Würstel war so heiß, ich hab mir fast die Zunge verbrannt!  3. Alter, das Würstchen war glühend heiß - fast hätt ich mir meine Geschmacksknospen ruiniert!"}]'::jsonb, ''),
  ('des-is-ka-mechanika-des-is-a-wiaschdl-dea-kaunn-ned-amoi-an-noogl-grod-eischloong', 'Des is ka Mechanika, des is a Wiaschdl - dea kaunn ned amoi an Noogl grod eischloong!', '', '', '', 'Wiener Mechaniker-Slang', 'Das ist kein Mechaniker, das ist ein Würschtel - der kann nicht einmal einen Nagel gerade einschlagen!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Mechaniker, sondern ein handwerklicher Totalausfall - der kann nicht einmal einen Nagel gerade einschlagen!\"  2. Das ist kein Mechaniker, das ist ein [[Vollwappler]] - der kann nicht einmal den Schraubenzieher gerade halten!  3. Das ist kein Mechaniker, sondern ein komplettes [[Weh]] - der schraubt verkehrt und wundert sich, warum’s locker wird!"}]'::jsonb, ''),
  ('waunnsd-wueuesd-kaunn-i-da-a-wiaschdl-scheissn', 'Waunnsd wüüsd, kaunn I da a Wiaschdl scheissn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Wenn du willst, kann ich dir ein Würschtel scheißen!', '[{"kategorie": "wörtlich", "text": "\"Wenn du willst, kann ich dir ''ne Kackwurst scheißen!\"  2. Wenn du willst, scheiß ich dir ''ne Kackwurst – samt Widmung und Dampfgarantie!  3. Erwart dir nix von mir – ich kann dir höchstens ''ne Kackwurst scheißen!"}]'::jsonb, ''),
  ('a-paarl-wiaschdl', 'a Paarl Wiaschdl', '', '', '', 'Wiener Würstelstandjargon', 'ein Paar Würschtel', '[{"kategorie": "wörtlich", "text": "\"ein Paar Würstel\""}, {"kategorie": "", "text": "\"ein Paar Brühwürste\""}, {"kategorie": "", "text": "\"ein Paar [[Frankfurter]]\""}, {"kategorie": "", "text": "\"ein Paar [[Debreziner]]\""}]'::jsonb, 'Host no a Paarl Wiaschdl fia mi? I bin aum Vahungan!'),
  ('host-no-a-paarl-wiaschdl-fia-mi-i-bin-aum-vahungan', 'Host no a Paarl Wiaschdl fia mi? I bin aum Vahungan!', '', '', '', 'Wiener Würstelstandjargon', 'Hast du noch ein Paar Würschtel für mich? Ich bin am Verhungern!', '[{"kategorie": "wörtlich", "text": "\"Hast du noch ein Paar Würstel im Kessel? Ich bin am Verhungern!\"  2. Hast du noch ein Paar Würstel für einen armen Tropf wie mich? Ich bin kurz vor''m Hungertod!  3. Hau mir bitte noch ein Paar Würstel rüber, bevor ich vom Fleisch falle!"}]'::jsonb, 'a Paarl Wiaschdl'),
  ('du-wiaschdl', 'Du Wiaschdl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du Würschtel!', '[{"kategorie": "wörtlich", "text": "\"Du Würstchen!\"  2. \"Du Versager!\"  3. \"Du [[Wappler]]!\"  4. \"Du [[Weh]]!\""}]'::jsonb, ''),
  ('dea-ghead-ind-wiaschd', 'Dea ghead ind Wiaschd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der gehört in die Würscht!', '[{"kategorie": "wörtlich", "text": "\"Der gehört in die Wurstmasse [[hineinfaschiert]]!\"  2. (scherzhaft für): \"Der ist zu absolut nichts zu gebrauchen - außer als Wurstmasse\"!  3. \"Den kannst in die Tonne kloppen!\"  4. \"Der taugt bestenfalls als Briefbeschwerer!\""}]'::jsonb, ''),
  ('des-is-ka-mechanika-des-is-a-voiwappla-dea-kaunn-ned-amoi-an-noogl-grod-eischloong', 'Des is ka Mechanika, des is a Voiwappla - dea kaunn ned amoi an Noogl grod eischloong!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist kein Mechaniker, das ist ein Vollwappler - der kann nicht einmal einen Nagel gerade einschlagen!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Mechaniker, sondern ein handwerklicher Totalausfall - der kann nicht einmal einen Nagel gerade einschlagen!\"  2. Das ist kein Mechaniker, das ist ein [[Vollkoffer]] - der kann nicht einmal den Schraubenzieher gerade halten!  3. Das ist kein Mechaniker, sondern ein komplettes [[Weh]] - der schraubt verkehrt und wundert sich, warum’s locker wird!"}]'::jsonb, ''),
  ('des-is-ka-mechanika-des-is-a-voiwaeae-dea-kaunn-ned-amoi-an-schraafnziaga-grod-hoidn', 'Des is ka Mechanika, des is a Voiwää - dea kaunn ned amoi an Schraafnziaga grod hoidn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist kein Mechaniker, das ist ein Vollweh - der kann nicht einmal einen Schraubenzieher gerade halten!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Mechaniker, sondern ein handwerklicher Totalausfall - der kann nicht einmal einen Schraubenzieher gerade halten!\"  2. Das ist kein Mechaniker, das ist ein [[Vollkoffer]] - der kann nicht einmal den Nagel gerade einschlagen!  3. Das ist kein Mechaniker, sondern ein  [[Vollwappler]] - der schraubt verkehrt und wundert sich, warum’s locker wird!"}]'::jsonb, ''),
  ('de-leewawuaschd-is-ned-jeedamaunns-soch-owa-fia-maunche-is-a-echts-soeoenfuada', 'De Leewawuaschd is ned jeedamaunns Soch - owa fia maunche is a echts Söönfuada!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Leberwurst ist nicht jedermanns Sache – aber für manche ist sie ein echtes Seelenfutter!', '[{"kategorie": "wörtlich", "text": "\"Nicht alle mögen Leberwurst, aber für manche ist sie echtes Wohlfühlessen!\"  2. Leberwurst ist nicht für jeden - aber für manche wie Balsam auf die Seele!  3. Nicht jeder liebt Leberwurst – aber für manche ist sie essbare Nostalgie!"}]'::jsonb, ''),
  ('du-beleidigde-leewawuaschd', 'Du beleidigde Leewawuaschd!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du beleidigte Leberwurst!', '[{"kategorie": "wörtlich, spöttisch-liebevoller Vorwurf an jemanden, der übertrieben empfindlich, schnell eingeschnappt oder beleidigt ist.", "text": "\"Du eingeschnappte Mimose!\"  2. \"Du zartbesaitetes Sensibelchen!\"  3. \"Du dünnhäutige Memme!\""}]'::jsonb, ''),
  ('schbueue-ned-auf-beleidigte-leewawuaschd', 'Schbüü ned auf beleidigte Leewawuaschd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Spiel nicht auf beledigte Leberwurst!', '[{"kategorie": "wörtlich", "text": "\"Spiel nicht grundlos das Sensibelchen!\"  2. \"Jetzt spiel dich nicht so auf, es war doch gar nichts!\"  3. \"Mach doch nicht aus jeder Kleinigkeit ein Drama!\"  4. Hör auf, beleidigt zu tun, und spiel nicht gleich die Mimose!"}]'::jsonb, ''),
  ('fias-wiaschdlgulasch-nimm-i-aum-liabsdn-debrezina-oda-knacka', 'Fias Wiaschdlgulasch nimm I aum liabsdn Debrezina oda Knacka!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Für das Würstelgulasch nehme ich am liebsten Debreziner oder Knacker!', '[{"kategorie": "wörtlich", "text": "\"Für das Würstelgulasch nehme ich am liebsten Debreziner-Würstel oder ''ne deftige Knackwurst!\"  2. Ich bereite mein Würstelgulasch am liebsten mit Debreziner-Würsteln oder ''ner deftigen Knackwurst zu!  3. Knacker und Debreziner bringen Biss und Würze ins Gulasch – und genau so soll’s sein!"}]'::jsonb, ''),
  ('wiaschdln-mit-soft', 'Wiaschdln mit Soft', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Würstel mit Saft', '[{"kategorie": "wörtlich", "text": "\"Frankfurter Würstel mit Gulaschsaftl\""}, {"kategorie": "", "text": "\"Frankfurter Würstchen mit Gulaschsooße\""}, {"kategorie": "Deutschland", "text": "\"Wiener Würstchen mit \"Gulaschtunke\""}]'::jsonb, 'Wiaschdln mit Soft - des is Soolfuud auf Wiinarisch!'),
  ('wiaschdln-mit-soft-des-is-soolfuud-auf-wiinarisch', 'Wiaschdln mit Soft - des is Soolfuud auf Wiinarisch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Würstel mit Saft – das ist Soulfood auf Wienerisch!', '[{"kategorie": "wörtlich", "text": "\"Würstel mit Saft – das ist Seelenfutter auf Wienerisch!\"  2. \"Frankfurter Würstchen mit Gulaschsooße - ein Klassiker der Wiener Wirtshausküche, der Leib und Seele wärmt!\"  3. (Deutschland): \"Wiener Würstchen mit \"Gulaschtunke - das ist echtes Wohlfühlessen aus Wien!\""}]'::jsonb, 'Wiaschdln mit Soft'),
  ('oida-dea-typ-hod-mi-voi-gneppd-90-euro-fiara-fejk-jackn-so-a-oasch', 'Oida, dea Typ hod mi voi gneppd - 90 Euro fiara Fejk-Jackn, so a Oasch!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Alter, der Typ hat mich voll geneppt – 90 Euro für ’ne Fake-Jacke, so ein Arsch!', '[{"kategorie": "wörtlich, Jugendjargon", "text": "\"Ey Digga, der Typ hat mich übel abgezogen – 90 Euro für ’ne billige Fake-Jacke. Was ein Hund!\"  2. Oh Mann, der Wichser hat mich voll abgezockt – 90 Euro für''n Plagiat, ich raste gleich aus!  3. Bruder, der hat mich richtig gefickt mit der Jacke – 90 Euro für ''nen billigen Plastikfetzen!"}]'::jsonb, ''),
  ('des-is-da-reinste-nepp-zeen-euro-fiara-lauwoams-bia', 'Des is da reinste Nepp - zeen Euro fiara lauwoams Bia!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Das ist der reinste Nepp - zehn Euro für ein lauwarmes Bier!', '[{"kategorie": "wörtlich", "text": "\"Das ist die reinste Abzocke - zehn Euro für ein lauwarmes Bier!\"  2. Zehn Euro für ein lauwarmes Bier - das ist blanker Wucher!  3. Zehn Euro für ein lauwarmes Bier sind schlichtweg Betrug am Kunden!"}]'::jsonb, ''),
  ('an-koidn-oasch-kriang', 'an koidn Oasch kriang', '', '', '', 'Tod und Sterben auf Wienerisch', 'einen kalten Arsch kriegen', '[{"kategorie": "wörtlich", "text": "\"einen kalten Arsch bekommen\""}, {"kategorie": "scherzhaft für", "text": "das Zeitliche segnen"}, {"kategorie": "", "text": "sterben, [[maukas]] gehen, [[ins]] Gras beißen, [[den]] Löffel abgeben, [[die]] Patschen strecken, [[die]] Eisen aufstellen, [[sich]] die Erdäpfel von unten ansehen"}]'::jsonb, 'Waunnsd kan koidn Oasch kriang wüüsd, rucksd de Marii in da Sekundn ausse!'),
  ('waunnsd-kan-koidn-oasch-kriang-wueuesd-rucksd-de-marii-in-da-sekundn-ausse', 'Waunnsd kan koidn Oasch kriang wüüsd, rucksd de Marii in da Sekundn ausse!', '', '', '', 'Wiener Gaunersprache', 'Wenn du keinen kalten Arsch kriegen willst, rückst du die Marie in der Sekunde raus!', '[{"kategorie": "wörtlich", "text": "\"Wenn das Geld nicht binnen einer Sekunde auf dem Tisch liegt, wirst du dir gleich einen kalten Arsch holen!\"  2. \"Willst du sterben oder zahlen? Such''s dir aus!\"  3. \"Geld auf den Tisch - oder ich sorg dafür, dass du dir die Erdäpfel von unten anschaust!\""}]'::jsonb, 'an koidn Oasch kriang'),
  ('si-in-oasch-auskeegln', 'si in Oasch auskeegln', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich den Arsch auskegeln', '[{"kategorie": "wörtlich", "text": "\"das Zeitliche segnen\""}, {"kategorie": "allg.", "text": "sterben, [[maukas]] gehn, [[ins]] Gras beißen, [[den]] Löffel abgeben, [[die]] Patschen strecken, [[die]] Eisen aufstellen, [[sich]] die Erdäpfel von unten anschauen"}]'::jsonb, 'Da scheensde Tood muass sei, waunnsda beim Puudan in Oasch auskeeglsd!'),
  ('da-scheensde-tood-muass-sei-waunnsda-beim-puudan-in-oasch-auskeeglsd', 'Da scheensde Tood muass sei, waunnsda beim Puudan in Oasch auskeeglsd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der schönste Tod muss sein, wenn du dir beim Pudern den Arsch auskegelst!', '[{"kategorie": "wörtlich", "text": "\"Der schönste Tod muss sein, wenn du dir beim Vögeln den Arsch auskegelst!\"  2. Es gibt wohl kein schöneres Ende, als beim Liebemachen den Löffel abzugeben!  3. Der königliche Abgang ist der, wenn man’s grad gemütlich miteinander treibt!"}]'::jsonb, 'si in Oasch auskeegln'),
  ('da-schuali-hod-si-in-oasch-auskeegld-jetzd-kemma-nua-no-dreiaschnopsn', 'Da Schuali hod si in Oasch auskeegld - jetzd kemma nua no Dreiaschnopsn!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Schurli hat sich den Arsch ausgekegelt - jetzt können wir nur noch Dreierschnapsen!', '[{"kategorie": "wörtlich", "text": "\"Der Schurli hat das Zeitliche gesegnet - jetzt können wir nur noch Dreierschnapsen!\"  2. Der Schurli hat die Patschen gestreckt - jetzt sind wir am Kartentisch nur noch zu dritt!  3. Der Schurli hat den letzten Stich gemacht – jetzt fehlt uns einer beim Abheben!"}]'::jsonb, ''),
  ('im-oasch-sei', 'im Oasch sei', '', '', '', 'Grundwortschatz Wienerisch', 'im Arsch sein', '[{"kategorie": "wörtlich, in Bezug auf Personen", "text": "\"geliefert sein\";  \"erledigt sein\", [[in Scheabm aufhoobn]]"}, {"kategorie": "in Bezug auf Dinge", "text": "\";  (von Dingen): \"im Eimer sein\", \"kaputt sein\", \"hinüber sein\", \"durch sein\""}]'::jsonb, 'Waunn de uns dawischn, samma im Oasch, Oida!'),
  ('waunn-de-uns-dawischn-samma-im-oasch-oida', 'Waunn de uns dawischn, samma im Oasch, Oida!', '', '', '', 'Wiener Gaunersprache', 'Wenn die uns erwischen, sind wir im Arsch, Alter!', '[{"kategorie": "wörtlich", "text": "\"Wenn die uns erwischen, sind wir geliefert, Bruder!\"  2. Wenn die uns hops nehmen, sind wir erledigt, Alter!  3. Wenn die uns schnappen, sitzen wir ganz tief in der Scheiße, mein Junge!"}]'::jsonb, 'im Oasch sei'),
  ('da-muarl-is-komplett-im-oasch-do-geed-nix-mea', 'Da Muarl is komplett im Oasch - do geed nix mea!', '', '', '', 'Wiener Mechaniker-Slang', 'Der Murl ist komplett im Arsch - da geht nichts mehr!', '[{"kategorie": "wörtlich", "text": "\"Der Motor ist komplett hinüber - da geht nichts mehr!\"  2. \"Der Motor ist komplett im Eimer - der macht keinen Mucks mehr!\"  3. \"Der Motor ist durch, da kannst du nichts mehr retten!\""}]'::jsonb, 'im Oasch sei'),
  ('mei-haendy-is-feinaelly-im-oasch-oida', 'Mei Händy is feinälly im Oasch, Oida!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Mein Handy ist finally im Arsch, Alter!', '[{"kategorie": "wörtlich", "text": "\"Mein Handy hat endgültig den Geist aufgegeben, Alter!\"  2. Bruder, mein Handy ist jetzt komplett im Eimer!  3. Das war''s. Mein Handy ist Geschichte, Alter - kaputt und total im Arsch!"}]'::jsonb, ''),
  ('ollas-zum-scheissn', 'Ollas zum Scheissn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Alles zum Scheißen!', '[{"kategorie": "wörtlich", "text": "\"Alles scheiße!\"  2. \"Alles Kacke!\"  3. \"Alles zum Vergessen!\"  4. \"Alles im Eimer!\"  5. [[Ollas Oasch!]]"}]'::jsonb, ''),
  ('in-oaschloch-faktoa-haum', 'in Oaschloch-Faktoa haum', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'den Arschloch-Faktor haben', '[{"kategorie": "wörtlich", "text": "\"einen skrupellosen Charakter haben\""}, {"kategorie": "", "text": "\"durch und durch ein Arschloch sein\""}, {"kategorie": "", "text": "\"sich keinen Deut um Moral scheren\""}]'::jsonb, 'Ea is schamant, schaud leiwaund aus - und hod trotzdem voi in Oaschloch-Faktor. Klassika!'),
  ('ea-is-schamant-schaud-leiwaund-aus-und-hod-trotzdem-voi-in-oaschloch-faktor-klassika', 'Ea is schamant, schaud leiwaund aus - und hod trotzdem voi in Oaschloch-Faktor. Klassika!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Er ist charmant, sieht spitze aus – und hat trotzdem voll den Arschloch-Faktor. Klassiker!', '[{"kategorie": "wörtlich", "text": "\"Sieht geil aus, redet charmant – und ist trotzdem das größte Arschloch. Klassiker!\"  2. Der Typ ist Tinder in Menschengestalt: sieht gut aus, ist aber durch und durch ein Arschloch!  3. Er sieht gut aus und weiß genau, wie man redet – aber innerlich ist er einfach ein Arsch. Klassiker!"}]'::jsonb, ''),
  ('beim-oasch-is-finsta', 'Beim Oasch is finsta!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Beim Arsch ist es finster!', '[{"kategorie": "wörtlich, Titel eines Musikstücks von W.A. Mozart, Köchelverzeichnis: KV Anh. C 9.03", "text": "\"Hinten raus wird''s düster!\"  2. (scherzhaft für): \"Es sieht schlecht aus!\"  3. \"Die Lage ist düster!\"  4. \"Am Ende der Fahnenstange wird''s finster!  5. \"Im Grab ist es finster!\""}]'::jsonb, ''),
  ('dea-typ-is-a-deaoatiga-madscho-der-daed-si-aum-liabsdn-soeoewa-puudan-waunna-kennd', 'Dea Typ is a deaoatiga Madscho - der däd si aum liabsdn sööwa puudan, waunna kennd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Typ ist ein derartiger Macho - der würde sich am liebsten selber pudern, wenn er könnte!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist so ein Macho - der würde sich am liebsten selbst vögeln, wenn er könnte!\"  2. Dieser Kerl ist sowas von einem Macho - null Charakter, aber dafür geil auf sich selbst!  3. Der Typ ist so selbstverliebt - der würde am liebsten sein eigenes Spiegelbild vögeln!"}]'::jsonb, ''),
  ('madscho-mit-oaschlochfaktoa', 'Madscho mit Oaschlochfaktoa', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Macho mit Arschlochfaktor', '[{"kategorie": "wörtlich", "text": "\"Alphamännchen mit skrupellosem Charakter\""}, {"kategorie": "", "text": "\"Chauvi mit ausgeprägt bösartigem Wesen\""}, {"kategorie": "", "text": "\"Egomane mit Killerinstinkt\""}, {"kategorie": "", "text": "\"Narzisst in Hochglanz\",  5. \"Luxusexemplar toxischer Männlichkeit\""}]'::jsonb, 'Dea Typ is a Madscho mit Oaschlochfaktoa - vapockd in Disajna-Hemd und Zaunpasta-Lächln!'),
  ('dea-typ-is-a-madscho-mit-oaschlochfaktoa-vapockd-in-disajna-hemd-und-zaunpasta-laechln', 'Dea Typ is a Madscho mit Oaschlochfaktoa - vapockd in Disajna-Hemd und Zaunpasta-Lächln!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der Typ ist ein Macho mit Arschlochfaktor - verpackt in Designerhemd und Zahnpasta-Lächeln!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist ein Luxusexemplar toxischer Männlichkeit – mit Designerhemd und dem moralischen Kompass eines Haifischs!\"  2. Der Kerl trägt Macho-Vibes in Hugo-Boss – außen Hochglanz, innen Abgrund!  3. Der Typ ist ein Egomane mit Killerinstinkt – kalter Arsch mit Gel im Haar und Zahnpasta-Lächeln!"}]'::jsonb, 'Madscho mit Oaschlochfaktoa'),
  ('da-madscho-duat-hintn-mocht-auf-dicke-hosn-soi-a-nua-ned-umfoin-waunns-glei-windig-wiad', 'Da Madscho duat hintn mocht auf dicke Hosn - soi a nua ned umfoin, waunns glei windig wiad!', '', '', '', 'Wiener Gaunersprache', 'Der Macho dort hinten macht auf dicke Hose – soll er nur nicht umfallen, wenn’s gleich windig wird!', '[{"kategorie": "wörtlich", "text": "\"Der Macho dort hinten macht auf Arnold Schwarzenegger, dabei haut ihn schon ein laues Lüfterl um!\"  2. Der Möchtegern-Macho dort hinten macht einen auf Goliath, dabei reicht ein kleiner David aus, dass er glei auf der [[Gosch]]''n liegt!\"  3. Der tut auf Kampfstier, aber wenn er ein bisschen Gegenwind spürt, fliegt er davon wie ein aufblasbares Gummihendl!"}]'::jsonb, ''),
  ('wea-imma-nua-liibe-duach-de-hintatia-mochd-brauchd-si-ned-wundan-waunns-iagendwaunn-amoi-oaschpuudara-zu-eam-soong', 'Wea imma nua Liibe duach de Hintatia mochd, brauchd si ned wundan, waunns iagendwaunn amoi ''Oaschpuudara'' zu eam soong!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wer immer nur Liebe durch die Hintertür macht, braucht sich nicht zu wundern, wenn sie irgendwann mal ''Arschpuderer'' zu ihm sagen!', '[{"kategorie": "wörtlich", "text": "\"Wer ständig Liebe durch die Hintertür macht, braucht sich nicht zu wundern, wenn die Leute irgendwann ''Arschficker'' zu ihm sagen!\"  2. Wer’s ständig hintenrum macht, muss mit dem Spitznamen \"Arschpuderer\" leben lernen!  3. Wer von hinten bohrt, kriegt halt vorne was zu hören!"}]'::jsonb, ''),
  ('dea-is-ka-tiimpleja-des-is-a-oaschpuudara-im-hintergrund', 'Dea is ka Tiimpleja - des is a Oaschpuudara im Hintergrund!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das ist kein Teamplayer - das ist ein Arschpuderer im Hintergrund!', '[{"kategorie": "wörtlich", "text": "\"Der ist kein Teamplayer – das ist ein intrigantes Arschloch, das im Hintergrund seine Fänden spinnt!\"  2. Der ist kein Mann der Gemeinschaft, sondern ein perfider Einzelgänger und ein hinterfotziges Arschloch!  3. Der gehört nicht ins Team – intrigiert ständig durch die Hintertür!"}]'::jsonb, ''),
  ('du-kaunnsd-mi-oaschpuudan', 'Du kaunnsd mi oaschpuudan!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du kannst mich arschpudern!', '[{"kategorie": "wörtlich", "text": "\"Du kannst mich in den Arsch ficken!\"  2. \"Du kannst mich mal!\"  3. \"Ich scheiß auf dich!\"  4. \"Du kannst mich mal kreuzweise!\""}]'::jsonb, ''),
  ('du-boochana-oaschpuudara', 'Du boochana Oaschpuudara!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du gebackener Arschpuderer!', '[{"kategorie": "wörtlich", "text": "\"Du schwuler Arschficker!\"  2. \"Du arschfickende Schwuchtel!\"  3. [[Du gsööchda Oaschbusarant!]]  4. [[Du ghaazda Beidlluutscha!]]"}]'::jsonb, 'Du gsööchda Oaschbusarant!'),
  ('du-gsoeoechda-oaschbusarant', 'Du gsööchda Oaschbusarant!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du geselchter Arschbuserant!', '[{"kategorie": "wörtlich", "text": "\"Du schwuler Arschficker!\"  2. [[Du boochana Oaschpuudara!]]  3. \"Du ghaazda Beidlluutscha!\""}]'::jsonb, 'Du boochana Oaschpuudara!'),
  ('du-ghaazda-beidlluutscha', 'Du ghaazda Beidlluutscha!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du geheizter Beidllutscher!', '[{"kategorie": "wörtlich", "text": "\"Du schwuler Schwanzlutscher!\"  2. [[Du boochana Oaschpuudara!]]  3. \"Du gsööchda Oaschbusarant!\""}]'::jsonb, 'Du boochana Oaschpuudara!'),
  ('zeaschd-woara-hetero-jetzd-isa-schwuul-waeu-ea-soogd-liawa-beidlluutscha-ois-futschlecka', 'Zeaschd woara hetero, jetzd isa schwuul - wäu ea soogd: ''Liawa Beidlluutscha ois Futschlecka!''', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Zuerst war er hetero, jetzt ist er schwul - weil er sagt: ''Lieber Beidllutscher als Futschlecker''!', '[{"kategorie": "wörtlich", "text": "\"Zuerst war er hetero, jetzt ist er schwul - denn er sagt: ''Lieber Pimmellutscher als Votzenlecker''!\"  2. Vom Rockjäger zum Schwanzversteher – oder wie er sagt: ''Ich hab umgesattelt, jetzt wird geblasen statt geschleckt!  3. „Hetero war gestern – heute leckt er nicht mehr Muschis, heute lutscht er Schwänze!"}]'::jsonb, ''),
  ('so-a-beidlluutscha-tuad-auf-freindlich-und-vapfeifd-mi-hintarucks-beim-schaeaef', 'So a Beidlluutscha - tuad auf freindlich und vapfeifd mi hintarucks beim Schääf!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'So ein Beidllutscher – tut auf freundlich und verpfeift dich hinterrücks beim Chef!', '[{"kategorie": "wörtlich", "text": "\"So ein Schwanzlutscher – tut auf freundlich, aber hintenrum verpfeift er dich beim Chef!\"  2. \"So ein hinterhältiger Wichser – tut auf Kumpel und verpfeift dich hinterrücks beim Chef!\"  3. So ein flascher Hund – grinst dir ins Gsicht und haut dir hintenrum das Messer ins Kreuz!"}]'::jsonb, ''),
  ('dea-busarant-schreibt-jeedn-toog-100-froong-ind-gruppn-und-ka-sau-leesds', 'Dea Busarant schreibt jeedn Toog 100 Froong ind Gruppn - und ka Sau leesds!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Buserant schreibt jeden Tag 100 Fragen in die Gruppe - und keine Sau liest''s!', '[{"kategorie": "wörtlich", "text": "\"Der lästige Vielschreiber haut täglich 100 Fragen in die Gruppe – aber interessieren tut’s genau null Leute!\"  2. Der nervige Quälgeist spamt die Gruppe voll mit Fragen – und kriegt nicht mal ein Emoji zurück!  3. Der penetrante Typ ballert jeden Tag 100 depperte Fragen in die Gruppe – und keine Sau interessiert’s!"}]'::jsonb, ''),
  ('busarantn-san-liibhoowa-da-griichischn-liibe-so-wia-da-platon-und-da-sokrates-zwa-filosoofn-mit-an-haung-zum-oaschpuudan', 'Busarantn san Liibhoowa da griichischn Liibe - so wia da Platon und da Sokrates, zwa Filosoofn mit an Haung zum Oaschpuudan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Buseranten sind Liebhaber der griechischen Liebe - so wie Platon und Sokrates, zwei Philosophen mit''m Hang zum Arschpudern!', '[{"kategorie": "wörtlich", "text": "\"Schwule sind Liebhaber der griechischen Liebe - so wie Platon und Sokrates, zwei Philosophen mit''m Hang zum Arschficken!\"  2. Griechische Liebe wird schon seit der Antike praktiziert - sogar Platon und Sokrates waren Buseranten mit ''ner ausgeprägten Vorliebe fürs eigene Geschlecht!  3. Buseranten sind Liebhaber der griechischen Liebe – so wie Platon und Sokrates, die schon vor 2.000 Jahren mehr an Knaben als an Mädels gedacht haben!"}]'::jsonb, ''),
  ('oaschbusarantn-san-liibhoowa-da-griichischn-liibe-so-wia-da-platon-und-da-sokrates-zwa-filosoofn-mit-an-haung-zum-oaschpuudan', 'Oaschbusarantn san Liibhoowa da griichischn Liibe - so wia da Platon und da Sokrates, zwa Filosoofn mit an Haung zum Oaschpuudan!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Arschbuseranten sind Liebhaber der griechischen Liebe - so wie Platon und Sokrates, zwei Philosophen mit''m Hang zum Arschpudern!', '[{"kategorie": "wörtlich", "text": "\"Schwule sind Liebhaber der griechischen Liebe - so wie Platon und Sokrates, zwei Philosophen mit''m Hang zum Arschficken!\"  2. Griechische Liebe wird schon seit der Antike praktiziert - sogar Platon und Sokrates waren Arschbuseranten mit ''ner ausgeprägten Vorliebe fürs eigene Geschlecht!  3. Arschbuseranten sind Liebhaber der griechischen Liebe – so wie Platon und Sokrates, die schon vor 2.000 Jahren mehr an Knaben als an Mädels gedacht haben!"}]'::jsonb, ''),
  ('da-dokta-soogd-es-is-nix-oags-nuara-oaschwaazn-schaud-owa-aus-wiara-dritta-oeoeboong', 'Da Dokta soogd, es is nix Oags, nuara Oaschwaazn - schaud owa aus wiara dritta Ööboong!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der Doktor sagt, es ist nichts Arges, nur eine Arschwarze - schaut aber aus wie ein dritter Ellbogen!', '[{"kategorie": "wörtlich", "text": "\"Der Doc sagt, es sei nichts Schlimmes, nur eine Warze am Hintern – schaut aber aus wie ein dritter Ellbogen!\"  2. \"Der Doc sagt, es sei nichts Schlimmes, nur ein Knubbel am Po – schaut aber aus wie so ’ne Mutanten-Arschwarze!\"  3. Manche kriegen mit 50 Rückenschmerzen, andere kriegen halt ''ne Arschwarze mitten am Hintern - aber laut Doc nichts Gefährliches!"}]'::jsonb, ''),
  ('mei-neiche-kolleegin-is-wiara-laestige-oaschwaazn-pickd-schdaendig-aun-mia-neafd-nonstop-und-geed-aafoch-ned-weg', 'Mei neiche Kolleegin is wiara lästige Oaschwaazn - pickd schdändig aun mia, neafd nonstop und geed aafoch ned weg!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Meine neue Kollegin ist wie ''ne lästige Arschwarze – pickt ständig an mir, nervt nonstop und geht einfach nicht weg!', '[{"kategorie": "wörtlich", "text": "\"Meine neue Kollegin klebt an mir wie ’ne lästige Arschwarze – geht nicht weg, nervt ständig und juckt dabei auch noch!\"  2. Meine neue Kollegin ist wie ein Knubbel am Po – ständig da, nervt immerzu, und geht einfach nicht weg!  3. Meine neue Kollegin ist wie ein Wimmerl am Arsch – sie klebt an mir, wächst sich immer mehr aus und lässt sich nicht abschütteln!"}]'::jsonb, ''),
  ('i-bin-aufgwochd-und-hob-glaubd-mia-is-iwa-nochd-a-dritte-oaschbockn-gwochsn-owa-zum-glick-woas-nua-a-muadstrumm-oaschwimmal', 'I bin aufgwochd und hob glaubd, mia is iwa Nochd a dritte Oaschbockn gwochsn - owa zum Glick woas nua a muadstrumm Oaschwimmal!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ich bin aufgewacht und hab geglaubt, mir ist über Nacht eine dritte Arschbacke gewachsen - aber zum Glück war''s nur ein mordstrumm Arschwimmerl!', '[{"kategorie": "wörtlich", "text": "\"Als ich aufwachte, dachte ich, mir sei über Nacht eine dritte Arschbacke gewachsen - aber zum Glück war''s nur ein Riesenpickel am Hintern!\"  2. Ich bin aufgewacht und dachte erst, ich hätt plötzlich ’nen Zusatzarsch – dabei war’s bloß ein fetter Knubbel am Hintern!  3. Ich hab geglaubt, ich bin über Nacht mutiert – zum Glück war der Hügel auf meinem Hintern aber nur ein riesiges Arschwimmerl!"}]'::jsonb, ''),
  ('da-bsoffane-duat-aun-da-schaunk-is-wiara-oaschwimmal-pickd-aum-wiatn-neafd-nonstop-und-geed-aafoch-ned-weg', 'Da Bsoffane duat aun da Schaunk is wiara Oaschwimmal - pickd aum Wiatn, neafd nonstop und geed aafoch ned weg!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Besoffene dort an der Schank ist wie ein Arschwimmerl - pickt am Wirten, nervt nonstop und geht einfach nicht weg!', '[{"kategorie": "wörtlich", "text": "\"Der Rauschbruder dort am Tresen klebt am Wirt wie ein lästiger Arschpickel – geht nicht weg, nervt ständig und juckt dabei auch noch!\"  2. Die Rauschkugel dort an der Schank ist wie ein Knubbel am Po – ständig da, nervt immerzu, und geht einfach nicht weg!  3. [[Der]] Bsuff dort an der Schank ist wie ein Wimmerl am Arsch – klebt am Wirten, wächst sich immer mehr aus und lässt sich nicht abschütteln!"}]'::jsonb, ''),
  ('wem-oofueuen', 'wem oofüün', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'jemanden abfüllen', '[{"kategorie": "wörtlich", "text": "\"jemanden abfüllen\" (vom mittelhochdeutschen \"abvüllen\"=\"abfüllen\")"}, {"kategorie": "scherzhaft für", "text": "\"jemanden betrunken machen\", \"jemandem reichlich Alkohol eingießen\" (bis dieser einen Rausch hat), \"jemanden auf Pegel bringen\", [[wem eitrangln]], [[hearichtn]]"}]'::jsonb, 'De haum den Neichn oogfüüd wiaran Öötanka - willkommen im Tiim!'),
  ('de-haum-den-neichn-oogfueued-wiaran-oeoetanka-willkommen-im-tiim', 'De haum den Neichn oogfüüd wiaran Öötanka - willkommen im Tiim!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die haben den Neuen abgefüllt wie einen Öltanker - willkommen im Team!', '[{"kategorie": "wörtlich", "text": "\"Die haben den Neuen abgefüllt wie ein Weinfass – willkommen an Bord!\"  2. \"Die haben den Neuen unter den Tisch gesoffen - Feuertaufe bestanden!\"  3. Die haben den Neuen mit Wein so vollgeschüttet, dass er glaubt, der Copyroom ist Ibiza!"}]'::jsonb, 'wem oofüün'),
  ('oogfueued-bis-zum-auschloog', 'oogfüüd bis zum Auschloog', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'abgefüllt bis zum Anschlag', '[{"kategorie": "wörtlich", "text": "\"abgefüllt bis Oberkante Unterlippe\""}, {"kategorie": "", "text": "\"voll wie zehn Russen\""}, {"kategorie": "", "text": "\"dicht bis untersDach\""}, {"kategorie": "", "text": "[[fett wiara Haubitzn]]"}]'::jsonb, 'Ooogfüüd bis zum Auschloog woita haamgee - owa ea is ned amoi bis zua Wiatshaustia kumma!'),
  ('oogfueued-wiara-oidoeoetank', 'oogfüüd wiara Oidöötank', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'abgefüllt wie ein Altöltank', '[{"kategorie": "wörtlich", "text": "\"abgefüllt bis Oberkante Unterlippe\""}, {"kategorie": "", "text": "\"voll wie zehn Russen\""}, {"kategorie": "", "text": "\"dicht bis untersDach\""}, {"kategorie": "", "text": "[[fett wiara Haubitzn]]"}]'::jsonb, 'Ooogfüüd wiara Oidöötank woita haamgee - owa ea is ned amoi bis zua Wiatshaustia kumma!'),
  ('voi-wia-zeen-russn', 'voi wia zeen Russn', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'voll wie zehn Russen', '[{"kategorie": "wörtlich", "text": "\"voll bis Oberkante Unterlippe\""}, {"kategorie": "", "text": "\"abgefüllt bis zum Anschlag\""}, {"kategorie": "", "text": "\"dicht bis untersDach\""}, {"kategorie": "", "text": "[[fett wiara Haubitzn]]"}]'::jsonb, 'Voi wia zeen Russn woita haamgee - owa ea is ned amoi bis zua Wiatshaustia kumma!'),
  ('dicht-bis-untas-doch', 'dicht bis untas Doch', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'dicht bis unters Dach', '[{"kategorie": "wörtlich", "text": "\"dicht bis Oberkante Unterlippe\""}, {"kategorie": "", "text": "\"abgefüllt bis zum Anschlag\""}, {"kategorie": "", "text": "\"voll wie zehn Russen\""}, {"kategorie": "", "text": "[[fett wiara Haubitzn]]"}]'::jsonb, 'Dicht bis untas Doch woita haamgee - owa ea is ned amoi bis zua Wiatshaustia kumma!'),
  ('ooogfueued-bis-zum-auschloog-woita-haamgee-owa-ea-is-ned-amoi-bis-zua-wiatshaustia-kumma', 'Ooogfüüd bis zum Auschloog woita haamgee - owa ea is ned amoi bis zua Wiatshaustia kumma!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Abgefüllt bis zum Anschlag wollte er heimgehen – aber er ist nicht einmal bis zur Wirtshaustür gekommen!', '[{"kategorie": "wörtlich", "text": "\"Voll wie zehn Russen wollte er heimgehen, aber er hat die Wirtshaustür nicht mehr gefunden!\"  2. Dicht bis unters Dach wollte er heimgehen – doch er ist nur bis zur Garderobe gekommen!  3. Abgefüllt wie ein Altöltank hat er sich auf den Nachhauseweg gemacht - doch zwischen Wirtshaustisch und Tür hat er den Kampf gegen die Schwerkraft verloren!"}]'::jsonb, 'oogfüüd bis zum Auschloog'),
  ('ooogfueued-wiara-oidoeoetank-woita-haamgee-owa-ea-is-ned-amoi-bis-zua-wiatshaustia-kumma', 'Ooogfüüd wiara Oidöötank woita haamgee - owa ea is ned amoi bis zua Wiatshaustia kumma!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Abgefüllt wie ein Altöltank wollte er heimgehen – aber er ist nicht einmal bis zur Wirtshaustür gekommen!', '[{"kategorie": "wörtlich", "text": "\"Voll wie zehn Russen wollte er heimgehen, aber er hat die Wirtshaustür nicht mehr gefunden!\"  2. Dicht bis unters Dach wollte er heimgehen – doch er ist nur bis zur Garderobe gekommen!  3. Abgefüllt bis zum Anschlag hat er sich auf den Nachhauseweg gemacht - doch zwischen Wirtshaustisch und Tür hat er den Kampf gegen die Schwerkraft verloren!"}]'::jsonb, 'oogfüüd wiara Oidöötank'),
  ('voi-wia-zeen-russn-woita-haamgee-owa-ea-is-ned-amoi-bis-zua-wiatshaustia-kumma', 'Voi wia zeen Russn woita haamgee - owa ea is ned amoi bis zua Wiatshaustia kumma!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Voll wie zehn Russen wollte er heimgehen – aber er ist nicht einmal bis zur Wirtshaustür gekommen!', '[{"kategorie": "wörtlich", "text": "\"Abgefüllt bis zum Anschlag wollte er heimgehen, aber er hat die Wirtshaustür nicht mehr gefunden!\"  2. Dicht bis unters Dach wollte er heimgehen – doch er ist nur bis zur Garderobe gekommen!  3. Abgefüllt wie ein Altöltank hat er sich auf den Nachhauseweg gemacht - doch zwischen Wirtshaustisch und Tür hat er den Kampf gegen die Schwerkraft verloren!"}]'::jsonb, 'voi wia zeen Russn'),
  ('dicht-bis-untas-doch-woita-haamgee-owa-ea-is-ned-amoi-bis-zua-wiatshaustia-kumma', 'Dicht bis untas Doch woita haamgee - owa ea is ned amoi bis zua Wiatshaustia kumma!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Dicht bis unters Dach wollte er heimgehen – aber er ist nicht einmal bis zur Wirtshaustür gekommen!', '[{"kategorie": "wörtlich", "text": "\"Abgefüllt bis zum Anschlag wollte er heimgehen, aber er hat die Wirtshaustür nicht mehr gefunden!\"  2. Voll wie zehn Russen wollte er heimgehen – doch er ist nur bis zur Garderobe gekommen!  3. Abgefüllt wie ein Altöltank hat er sich auf den Nachhauseweg gemacht - doch zwischen Wirtshaustisch und Tür hat er den Kampf gegen die Schwerkraft verloren!"}]'::jsonb, 'dicht bis untas Doch'),
  ('do-kaunnsd-da-olle-zeen-finga-ooschleckn', 'Do kaunnsd da olle zeen Finga ooschleckn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da kannst du dir alle zehn Finger abschlecken!', '[{"kategorie": "scherzhaft für", "text": "\"Da kannst du dich mehr als glücklich schätzen!\"  2. Da hast du echt einen Glücksgriff gemacht!  3. Davon können andere nur träumen!  4. Da hast du wirklich Schwein gehabt!"}]'::jsonb, ''),
  ('noch-jeeda-famuelienfeia-hob-i-a-fotzbloodan-waeu-waunnsd-kummsd-und-geesd-wiasd-von-olle-oogschleckd-und-eigschbeichld', 'Noch jeeda Famülienfeia hob I a Fotzbloodan - wäu waunnsd kummsd und geesd, wiasd von olle oogschleckd und eigschbeichld!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Nach jeder Familienfeier hab ich ''ne Fotzblattern - weil wennst kommst und gehst, wirst von allen abgeschleckt und eingespeichelt!', '[{"kategorie": "wörtlich", "text": "\"Nach jeder Familienfeier hab ich ''ne Fieberblase - denn wennst kommst und gehst, wirst du von allen abgeschleckt und eingespeichelt!\"  2. Nach jeder Familienfeier wächst mir ''ne Fieberblase - denn wenn du kommst und gehst, wirst du von allen durchgeknutscht und vollgesabbert!  3. Ich krieg nach jeder Familienfeier ''ne Fieberblase - denn so abgeleckt, eingespeichelt und zusammengeschmust wirst du sonst nirgends!"}]'::jsonb, ''),
  ('mit-seine-oogschleckdn-hoa-schauda-aus-ois-haeda-in-schaeaedl-ins-frittiaoeoe-tauchd', 'Mit seine oogschleckdn Hoa schauda aus, ois häda in Schäädl ins Frittiaöö tauchd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit seinen abgeschleckten Haaren sieht er aus, als hätte er den Schädel ins Frittieröl getaucht!', '[{"kategorie": "wörtlich", "text": "\"Mit seinen abgeleckten Haaren sieht er aus, als hätte er seinen Kopf ins Frittieröl getaucht!\"  2. Seine Frisur wirkt wie lackiert – als hätt er sich die Haare mit Frittierfett eingecremt!  3. Schau dir seine Haare an - ultragegelt, als hätt er sich mit Bratfett frisiert!"}]'::jsonb, ''),
  ('dea-schaud-heit-aus-wia-oogeschleckd-ois-warada-frisch-ausn-kataloog-gfloong', 'Dea schaud heit aus wia oogeschleckd - ois warada frisch ausn Kataloog gfloong!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der schaut heute aus wie abgeschleckt - als wäre er frisch aus dem Katalog geflogen!', '[{"kategorie": "wörtlich", "text": "\"Der sieht heute aus wie abgeleckt - als wäre er frisch aus dem Katalog geflogen!\"  2. Der ist heute rausgeputzt bis zum Abwinken – als hätte ihn ein Stylist im Schlaf zurechtgebügelt!  3. Der ist heute so schick aufgetakelt - den könntest du in der Auslage ausstellen!"}]'::jsonb, ''),
  ('mit-sein-oogschleckdn-gfriiss-schauda-aus-wiara-schwiigasoon-den-kaana-wueue', 'Mit sein oogschleckdn Gfriiss schauda aus wiara Schwiigasoon, den kaana wüü!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit seinem abgeschleckten Gfrieß schaut er aus wie ein Schwiegersohn, den keiner will!', '[{"kategorie": "wörtlich", "text": "\"Mit seiner glattgeleckten Fratze sieht er aus wie ein Schwiegersohn, den keiner will!\"  2. Mit seiner hochglanzpolierten Visage wirkt er wie ein Schwiegersohn, den man nicht einmal seiner Schwiegermutter wünscht!  3. Mit seiner eingebildeten, lackierten Fresse sieht er aus wie der Musterknabe aus der Hölle!"}]'::jsonb, ''),
  ('neebm-dem-oogschleckdn-schaud-de-braut-aus-wia-frisch-ausn-bett-gfoin', 'Neebm dem Oogschleckdn schaud de Braut aus wia frisch ausn Bett gfoin!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Neben dem Abgeschleckten schaut die Braut aus wie frisch aus dem Bett gefallen!', '[{"kategorie": "wörtlich", "text": "\"Neben dem Aufgebrezelten sieht die Braut aus wie frisch aus dem Bett gefallen!\"  2. Im Vergleich zu dem aalglatten Typen sieht die Braut ziemlich zerknautscht aus!  3. Neben dem glattgeleckten Gockel sieht die Braut aus, als wäre sie gerade aus dem Bett gefallen!"}]'::jsonb, ''),
  ('ookrotzn-miass-ma-olle-i-wueue-nua-ned-da-easchde-sei', 'Ookrotzn miass ma olle - I wüü nua ned da Easchde sei!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Abkratzen müssen wir alle - ich will nur nicht der Erste sein!', '[{"kategorie": "wörtlich", "text": "\"Sterben müssen wir alle - ich will nur nicht der Erste sein!\"  2. Irgendwann müssen wir alle den Löffel abgeben – aber bitte nicht ich zuerst!  3. Irgendwann beißen wir alle ins Gras - ich will nur nicht als Erster drunterliegen!"}]'::jsonb, ''),
  ('si-aubechan', 'si aubechan', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich anbechern', '[{"kategorie": "wörtlich", "text": "\"sich anbechern\" (vom mittelhochdeutschen \"becheren\"=\"bechern\")"}, {"kategorie": "allg.", "text": "sich einen Rausch antrinken, [[si autrangln]], [[si auduudln]], [[si autschechan]], [[si aubloosn]], [[si auflaschln]], [[si auschwappn]], [[si auschwaassn]], [[si aurealn]], [[si auduusln]]"}]'::jsonb, 'Ea hod si laungsaum, owa züüsicha aubechad, bisa umkippd is!'),
  ('ea-hod-si-laungsaum-owa-zueuesicha-aubechad-bisa-umkippd-is', 'Ea hod si laungsaum, owa züüsicha aubechad, bisa umkippd is!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er hat sich langsam, aber zielsicher angebechert, bis er umgekippt ist!', '[{"kategorie": "wörtlich", "text": "\"Er hat sich Zug um Zug angebechert, bis er umgefallen ist!\"  2. Er hat sich sauber zugesoffen – Schluck für Schluck, bis er aus den Latschen gekippt ist!  3. Er hat sich mit Stil angebechert und sich Tropfen für Tropfen in den Untergang georgelt!"}]'::jsonb, ''),
  ('heast-augschissana-bist-deppad', 'Heast, Augschissana, bist deppad?', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Hör mal, Angeschissener, bist du deppert?', '[{"kategorie": "wörtlich", "text": "\"Hör mal, du Scheißkerl, bist du deppert?\"  2. Hör mal, du Flachwichser, hast du noch alle?  3. Pass bloß auf, du Blödmann!  4. Nimm dich in Acht, du Volltrottel!"}]'::jsonb, ''),
  ('mit-soiche-augschissanan-kaunnsd-kann-bruch-plaanan-de-haum-vuahea-scho-de-hoosn-voi', 'Mit soiche Augschissanan kaunnsd kann Bruch plaanan - de haum vuahea scho de Hoosn voi!', '', '', '', 'Wiener Gaunersprache', 'Mit solchen Angeschissenen kannst du keinen Bruch planen – die haben vorher schon die Hosen voll!', '[{"kategorie": "wörtlich", "text": "\"Mit solchen Weicheiern kannst du keinen Einbruchscoup planen – die haben ja vorher schon die Hosen voll!\"  2. Mit solchen Hosenscheißern brauchst du keinen Bruch starten – die zittern ja schon beim Türknauf!  3. Mit diesen Flachwichsern  brichst du höchstens in Tränen aus – aber sicher nicht in Häuser ein!"}]'::jsonb, ''),
  ('si-woa-ia-leebdooch-laung-a-oams-klaans-bschissal-de-hod-sogoa-beim-eiakochn-ziidad', 'Si woa ia Leebdooch laung a oams, klaans Bschissal - de hod sogoa beim Eiakochn ziidad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sie war ihr Lebtag lang ein armes, kleines Bschisserl - die hat sogar beim Eierkochen gezittert!', '[{"kategorie": "wörtlich", "text": "\"Sie war ihr Leben lang ein armes, hilfloses Schisserchen - die hat sogar beim Eierkochen gezittert!\"  2. Sie war ihr Leben lang ein armes, ängstliches Würstchen - die hat sich vor ihrem eigenen Schatten gefürchtet!  3. Sie war ihr Leben lang ein zitterndes Nervenbündel – schon bei Kleinigkeiten hat sie Herzklopfen bekommen!"}]'::jsonb, ''),
  ('heast-du-bschissal-du-ziidasd-jo-mea-oisa-jungfrau-vuam-easchdn-dildo-und-so-aana-wueue-eibrecha-sei', 'Heast, du Bschissal, du ziidasd jo mea oisa Jungfrau vuam easchdn Dildo - und so aana wüü Eibrecha sei!', '', '', '', 'Wiener Gaunersprache', 'Hör mal, du Schisser, du zitterst ja mehr als ''ne Jungfrau vorm ersten Dildo - und so einer will Einbrecher sein!', '[{"kategorie": "wörtlich", "text": "\"Hör mal, du Hosenscheißer, du bist ja bleicher im Gesicht als ''ne Jungfrau vorm ersten Mal - und so einer will Einbrecher sein!\"  2. Hey, du Flachwichser, mit dem Händeflattern willst du Schlösser knacken? Bleib lieber bei Monopoly, Cowboy!  3. Ein Waschlappen wie du kriegt ja schon Schweißausbruch beim Klingeln – und du willst  ''nen Safe knacken?"}]'::jsonb, ''),
  ('si-eiweimpaln', 'si eiweimpaln', '', '', '', 'Grundwortschatz Wienerisch', 'sich einweimperln', '[{"kategorie": "wörtlich", "text": "\"sich einweimperln\" (von [[Weimberl]] = \"Weinbeerchen\", vom mittelhochdeutschen \"wīnbere\"=\"Weinbeere\")"}, {"kategorie": "allg.", "text": "\"sich honigsüß einschmeicheln\", \"sich einschleimen\", \"sich ranschleimen\", \"sich Liebkind machen\", [[wem in Oasch kräun]]"}]'::jsonb, 'Von mir aus kaunnst di no zeen Joa bei mia eiweimpaln - den Postn kriagst trotzdem ned!'),
  ('von-mir-aus-kaunnst-di-no-zeen-joa-bei-mia-eiweimpaln-den-postn-kriagst-trotzdem-ned', 'Von mir aus kaunnst di no zeen Joa bei mia eiweimpaln - den Postn kriagst trotzdem ned!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Von mir aus kannst du dich noch zehn Jahre bei mir einweimperln - den Posten kriegst du trotzdem nicht!', '[{"kategorie": "wörtlich", "text": "\"Von mir aus kannst du noch zehn Jahre bei mir rumschleimen – du kriegst den Job trotzdem nicht!\"  2. Egal wie oft du dich ranschleimst – den Posten kriegst du nicht!  3. Mach ruhig weiter auf honigsüß –  aber den Job kriegst du nicht! ([[si eiweimpaln]])"}]'::jsonb, 'si eiweimpaln'),
  ('wia-kauma-nua-so-hianamputiad-paarkn', 'Wia kauma nua so hianamputiad paarkn?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie kann man nur so hirnamputiert parken?', '[{"kategorie": "wörtlich", "text": "\"Wie kann man nur so hirnbefreit parken?\"  2. Wie zum Teufel kriegt man es hin, so behindert zu parken?  3. Was für ein hirntoter Vollidiot hat das Auto hier abgestellt?"}]'::jsonb, ''),
  ('du-hianamputiada-flochwichsa', 'Du hianamputiada Flochwichsa!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du hirnamputierter Flachwichser!', '[{"kategorie": "wörtlich", "text": "\"Du hirnbefreiter Wappler!\" 2. [[Du geistigs Nockapatzl!]]  3. [[Du hirnamputierter Flachwichser!]]"}]'::jsonb, ''),
  ('du-geistigs-nockapatzl', 'Du geistigs Nockapatzl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du geistiges Nackerpatzl!', '[{"kategorie": "wörtlich", "text": "\"Du geistiger Tiefflieger!\"  2. \"Du hirnbefreiter Wappler!\"  3. [[Du deppada Oasch mit Uan!]]"}]'::jsonb, 'Du hianamputiada Flochwichsa!'),
  ('du-deppada-oasch-mit-uan', 'Du deppada Oasch mit Uan!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du depperter Arsch mit Ohren!', '[{"kategorie": "wörtlich", "text": "\"Du hirnbefreiter Wappler!\" 2. [[Du geistigs Nockapatzl!]]  3. [[Du hirnamputierter Flachwichser!]]"}]'::jsonb, 'Du geistigs Nockapatzl!'),
  ('a-hian-wiara-nuudlsiib-haum', 'a Hian wiara Nuudlsiib haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Hirn wie ein Nudelsieb haben', '[{"kategorie": "wörtlich", "text": "\"ein Hirn wie ein Spaghettisieb haben\""}, {"kategorie": "", "text": "\"ein löchriges Gedächtnis wie Schweizer Käse haben\""}, {"kategorie": "", "text": "[[a Hian wiara Netzleiwal haum]]"}, {"kategorie": "", "text": "[[a Hian wiara Ochtlgauns haum]]"}]'::jsonb, 'Dea hod a Hian wiara Nuudlsiib - do pfeifd da Wind duach wia duach a hiinichs Zööd!'),
  ('dea-hod-a-hian-wiara-nuudlsiib-do-pfeifd-da-wind-duach-wia-duach-a-hiinichs-zoeoed', 'Dea hod a Hian wiara Nuudlsiib - do pfeifd da Wind duach wia duach a hiinichs Zööd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat ein Hirn wie ein Nudelsieb - da pfeift der Wind durch wie durch ein hinniges Zelt!', '[{"kategorie": "wörtlich", "text": "\"Der hat ein Hirn wie ein Spaghettisieb - da pfeift der Wind durch wie durch ein kaputtes Zelt!\"  2. Der hat ein Hirn wie ein löchriges Sieb – da zieht der Wind durch wie durch ein undichtes Zelt!  3. Der hat ein Hirn wie ein Nudelsieb - wenn du da einen Gedanken reinschickst, kommt er am anderen Ende ungefiltert wieder raus!"}]'::jsonb, 'a Hian wiara Nuudlsiib haum'),
  ('a-hian-wiara-ochtlgauns-haum', 'a Hian wiara Ochtlgauns haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Hirn wie eine Achtelgans haben', '[{"kategorie": "wörtlich", "text": "\"ein Hirn haben, das achtmal kleiner ist als das einer ausgewachsenen, dummen Gans\""}, {"kategorie": "scherzhaft für", "text": "\"ein löchriges Gedächtnis wie Schweizer Käse haben\""}, {"kategorie": "", "text": "[[a Hian wiara Nuudlsiib haum]]"}, {"kategorie": "", "text": "[[a Hian wiara Netzleiwal haum ]]"}]'::jsonb, 'a Hian wiara Nuudlsiib haum'),
  ('si-hod-a-hian-wiara-ochtlgauns-des-reicht-grod-moi-fias-schnoodan-und-schimpfn', 'Si hod a Hian wiara Ochtlgauns - des reicht grod moi fias Schnoodan und Schimpfn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sie hat ein Hirn wie ''ne Achtelgans - das reicht gerade mal fürs Schnattern und Schimpfen!', '[{"kategorie": "wörtlich", "text": "\"Sie hat ein Hirn, das achtmal kleiner ist als das einer ausgewachsenen, dummen Gans - das reicht grad mal zum Schnattern und Schimpfen!\"  2. Sie ist achtmal blöder als eine ausgewachsene, dumme Gans - das reicht grad mal zum Schnattern und Schimpfen!  3. Sie ist intellektuell dieSparversion einer dummen Gans mit ''nem Kleinhirn hoch acht – zum Denken zu wenig, zum Schnattern zu viel!"}]'::jsonb, 'a Hian wiara Ochtlgauns haum'),
  ('a-hian-wiara-netzleiwal-haum', 'a Hian wiara Netzleiwal haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Hirn wie ein Netzleibchen haben', '[{"kategorie": "wörtlich", "text": "\"ein Gedächtnis wie löchriger Schweizer Käse haben\""}, {"kategorie": "", "text": "[[a Hian wiara Nuudlsieb haum]]"}, {"kategorie": "", "text": "[[a Hian wiara Ochtlgauns haum]]"}]'::jsonb, 'a Hian wiara Nuudlsiib haum'),
  ('de-koeoenarin-hod-a-hian-wiara-netzleiwal-laenga-ois-fuenf-minuutn-bleibd-do-nix-drin-haenga', 'De Köönarin hod a Hian wiara Netzleiwal - länga ois fünf Minuutn bleibd do nix drin hänga!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Kellnerin hat ein Hirn wie ein Netzleibchen - länger als fünf Minuten bleibt da drin nichts hängen!', '[{"kategorie": "wörtlich", "text": "\"Die Kellnerin hat ein Hirn wie ein Nudelsieb – alles läuft durch, nichts bleibt hängen!\"  2. Die Kellnerin hat ein Hirn wie ein Fischernetz – große Maschen, nix drin!  3. Die Kellnerin hat das Hirn eines löchrigen Schweizer Käses - alles flutscht durch, nichts bleibt hängen!"}]'::jsonb, 'a Hian wiara Netzleiwal haum')
